// 產生檔：node tools/build_course_v2.js（來源 tools/content/course_v2/）。不要手改。
window.BUZZ_COURSE_V2_LESSONS = Object.assign(window.BUZZ_COURSE_V2_LESSONS || {}, {"average-rate":{"id":"average-rate","prerequisites":["function-intro"],"next":["secant-to-tangent"],"related":["derivative-definition"],"objectives":["會算 f 在 [a, b] 上的平均變化率 (f(b) − f(a))/(b − a)，並說出它的單位。","知道它在圖上是兩點連線（割線）的斜率，正負代表平均上升或下降。","會把區間寫成 [a, a + h]，算出 (f(a + h) − f(a))/h 並化簡。"],"concept":[{"heading":"① 從「平均多快」開始","body":["開車 2 小時走了 120 公里，平均時速是 120 ÷ 2 = 60 公里／小時。這個數不管中間塞不塞車，只看頭尾：位置變了多少，除以時間過了多久。","把位置寫成時間的函數 s(t)，從 t = a 到 t = b 的平均速度就是 (s(b) − s(a))/(b − a)。"]},{"heading":"② 任何函數都可以這樣問","body":["對一般的函數 y = f(x)，x 從 a 變到 b，輸出變了 Δy = f(b) − f(a)，輸入變了 Δx = b − a。兩者相除，叫做 f 在 [a, b] 上的平均變化率：每增加一單位的 x，y 平均變了多少。","單位是「y 的單位 ÷ x 的單位」：位置對時間是公尺／秒，成本對產量是元／件。"],"tex":["\\frac{\\Delta y}{\\Delta x}=\\frac{f(b)-f(a)}{b-a}"]},{"heading":"③ 圖上看：割線的斜率","body":["在圖形上取 A(a, f(a)) 與 B(b, f(b)) 兩點，連起來的直線叫割線。它的斜率是「鉛直變化 ÷ 水平變化」，正好就是上面的式子。所以平均變化率 = 割線斜率。","正的代表從 A 到 B 平均是上升，負的代表平均下降。等於 0 只代表頭尾一樣高，中間可能上去又下來，不代表 f 沒有變。"]},{"heading":"④ 用 a 與 h 來寫","body":["之後最常用的寫法是：從 a 出發，往右走 h，也就是區間 [a, a + h]。這時 Δx = h，平均變化率是 (f(a + h) − f(a))/h。","h 也可以是負的，代表往左走；式子不用改，因為分子分母同時變號。下一課〈割線到切線〉要做的事，就是讓 h 越來越小。"],"tex":["\\frac{f(a+h)-f(a)}{h}"]}],"workedExamples":[{"title":"多項式在一段區間上","prompt":"f(x) = x²，求 f 在 [1, 3] 上的平均變化率。","steps":["Δy = f(3) − f(1) = 9 − 1 = 8。","Δx = 3 − 1 = 2。","平均變化率 = 8/2 = 4：x 每增加 1，x² 在這段平均增加 4。","圖上：通過 (1, 1) 與 (3, 9) 的割線斜率是 4。"],"answer":"4"},{"title":"落下的石頭：負的平均速度","prompt":"石頭從 80 公尺高處落下，t 秒後高度 h(t) = 80 − 4.9t²（公尺）。求前 2 秒的平均速度。","steps":["h(2) = 80 − 4.9 · 4 = 80 − 19.6 = 60.4；h(0) = 80。","平均速度 = (h(2) − h(0))/(2 − 0) = (60.4 − 80)/2 = −19.6/2 = −9.8。","單位是公尺／秒。負號表示高度在減少，也就是往下掉。"],"answer":"−9.8 公尺／秒","note":"這是 2 秒內的平均。「第 2 秒那一瞬間多快」是另一個問題，要等〈導數定義〉。"},{"title":"區間寫成 [3, 3 + h]","prompt":"f(x) = x²，化簡 f 在 [3, 3 + h] 上的平均變化率（h ≠ 0），並算 h = 0.1、0.01 時的值。","steps":["f(3 + h) = (3 + h)² = 9 + 6h + h²，所以 f(3 + h) − f(3) = 6h + h²。","除以 Δx = h：(6h + h²)/h = 6 + h。約掉 h 可以，因為 h ≠ 0。","h = 0.1 得 6.1；h = 0.01 得 6.01。"],"answer":"6 + h；6.1、6.01","note":"h 越小，平均變化率越靠近 6。這個「靠近」就是下一課的主角。"}],"pitfalls":["分子用 f(b) − f(a)，分母卻寫 a − b，正負號整個反過來。","把平均變化率和「兩端函數值的平均」(f(a) + f(b))/2 搞混。","忘了除以 Δx，只算 f(b) − f(a)。","平均變化率是 0，就以為 f 在這段完全沒動。","答案不寫單位，或把單位寫成 x 的單位 ÷ y 的單位。"],"checks":[{"ask":"f(x) = x³ 在 [0, 2] 上的平均變化率是？","options":[{"label":"4","correct":true},{"label":"8","why":"8 是 f(2) − f(0)，還要除以 Δx = 2。"},{"label":"12","why":"12 是 x³ 在 x = 2 那一點的斜率（之後會學），不是整段的平均。整段是 (8 − 0)/(2 − 0) = 4。"}]},{"ask":"一個水箱的水量 V(t)（公升，t 以分鐘計），V(10) = 50、V(4) = 80。從 t = 4 到 t = 10 的平均變化率是？","options":[{"label":"−5 公升／分鐘","correct":true},{"label":"5 公升／分鐘","why":"分子是 V(10) − V(4) = −30，水在減少，答案要是負的。"},{"label":"−1/5 分鐘／公升","why":"分子分母放反了：要水量變化除以時間變化。"}]},{"ask":"f 在 [a, b] 上的平均變化率，在圖上是什麼？","options":[{"label":"通過 (a, f(a)) 與 (b, f(b)) 的直線的斜率","correct":true},{"label":"曲線在 x = a 的切線斜率","why":"切線只用到一個點；平均變化率用的是兩個點，所以是割線。"},{"label":"曲線在 [a, b] 底下的面積","why":"面積是另一回事（之後的積分）；這裡是「鉛直變化 ÷ 水平變化」。"}]},{"ask":"f(x) = x² 在 [2, 2 + h] 上的平均變化率（h ≠ 0）化簡後是？","options":[{"label":"4 + h","correct":true},{"label":"4","why":"(2 + h)² − 4 = 4h + h²，除以 h 是 4 + h；h² 那項沒有消失。"},{"label":"(4 + h)/h","why":"分子 4h + h² 每一項都有 h，除以 h 之後分母就沒有 h 了。"}]}],"practice":[]},"secant-to-tangent":{"id":"secant-to-tangent","prerequisites":["average-rate","limit-intro","limit-factor"],"next":["derivative-definition"],"related":["limit-one-sided","limit-rationalize"],"objectives":["說出切線斜率是「割線斜率在 h → 0 時的極限」。","用這個極限算出多項式、1/x 在某一點的切線斜率。","用點斜式寫出切線方程式。","知道切線不是「只碰曲線一次的直線」。"],"concept":[{"heading":"① 一點算不出斜率","body":["曲線在某一點有多斜？直覺上是那一點切線的斜率。問題是斜率要兩個點才算得出來，切線上我們只知道一個點 P。","辦法是先借第二個點。P = (a, f(a))，Q = (a + h, f(a + h))，割線 PQ 的斜率就是上一課的平均變化率 (f(a + h) − f(a))/h。"]},{"heading":"② 讓 Q 滑向 P","body":["以 f(x) = x²、a = 1 為例：割線斜率 = ((1 + h)² − 1)/h = (2h + h²)/h = 2 + h（h ≠ 0）。","h = 0.1、0.01 得 2.1、2.01；h = −0.01、−0.1 得 1.99、1.9。Q 從兩邊靠近 P，割線斜率都往 2 擠。","h 不能直接代 0：Q 跟 P 重合時只剩一個點，式子是 0/0。所以這是一個極限：切線斜率 = lim_{h→0} 割線斜率。"]},{"heading":"③ 切線的定義","body":["曲線在 P 的切線，是通過 P、斜率等於下面這個極限的直線（極限要存在）。","國中的圓「只碰一次」的說法，對一般曲線不對：y = x³ 在 (1, 1) 的切線會在 x = −2 再碰到曲線（範例 3）；反過來，鉛直線 x = 1 只碰 y = x² 一次，卻不是切線。"],"tex":["m=\\lim_{h\\to0}\\frac{f(a+h)-f(a)}{h}"]},{"heading":"④ 有了斜率，寫出直線","body":["通過 (a, f(a))、斜率 m 的直線：y − f(a) = m(x − a)。上面 y = x² 在 (1, 1) 的切線是 y − 1 = 2(x − 1)，也就是 y = 2x − 1。","左右兩邊的割線斜率擠向不同的數時（例如 |x| 在 0，右邊一直是 1、左邊一直是 −1，見〈左極限與右極限〉），極限不存在，那一點就沒有切線。"]}],"workedExamples":[{"title":"y = x² 在 x = 1","prompt":"求 y = x² 在 x = 1 的切線斜率與切線方程式。","steps":["割線斜率：((1 + h)² − 1²)/h = (1 + 2h + h² − 1)/h = (2h + h²)/h。","h ≠ 0，約掉 h：2 + h。","h → 0：斜率 m = 2。","點斜式：y − 1 = 2(x − 1)，即 y = 2x − 1。"],"answer":"斜率 2；y = 2x − 1"},{"title":"y = 1/x 在 x = 2：要先通分","prompt":"求 y = 1/x 在 x = 2 的切線斜率與切線方程式。","steps":["割線斜率：(1/(2 + h) − 1/2)/h。","分子通分：1/(2 + h) − 1/2 = (2 − (2 + h))/(2(2 + h)) = −h/(2(2 + h))。","除以 h（h ≠ 0）：−1/(2(2 + h))。","h → 0：m = −1/(2 · 2) = −1/4。","切點是 (2, 1/2)：y − 1/2 = −(1/4)(x − 2)，即 y = −x/4 + 1。"],"answer":"斜率 −1/4；y = −x/4 + 1"},{"title":"切線可以再碰到曲線","prompt":"求 y = x³ 在 x = 1 的切線，並找出它和曲線的其他交點。","steps":["割線斜率：((1 + h)³ − 1)/h = (3h + 3h² + h³)/h = 3 + 3h + h²（h ≠ 0）。h → 0 得 m = 3。","切線：y − 1 = 3(x − 1)，即 y = 3x − 2。","交點：x³ = 3x − 2，也就是 x³ − 3x + 2 = 0。x = 1 一定是根，分解得 (x − 1)²(x + 2) = 0。","所以除了切點，切線還在 x = −2、點 (−2, −8) 穿過曲線。"],"answer":"y = 3x − 2；另一交點 (−2, −8)"}],"pitfalls":["在割線斜率裡直接代 h = 0，得到 0/0 就停住。要先化簡、約掉 h。","只從一邊看（只試 h > 0），沒有確認左右擠向同一個數。","斜率算對了，切線卻寫成 y = mx，忘了要通過切點 (a, f(a))。","以為切線只能碰曲線一次。","展開 (a + h)² 漏掉 2ah 那一項。"],"figures":[{"caption":"拖 h 讓 Q 滑向 P，割線轉成切線","after":1,"widget":{"type":"secant-tangent","f":"x^2","a":1,"h":[-1.5,1.5],"value":1,"window":[-1,3,-1,6]}}],"checks":[{"ask":"y = x² 在 x = 3 的切線斜率是？","options":[{"label":"6","correct":true},{"label":"9","why":"9 是 f(3)，是切點的高度，不是斜率。割線斜率 ((3 + h)² − 9)/h = 6 + h → 6。"},{"label":"6 + h","why":"6 + h 是割線斜率；切線斜率要再讓 h → 0。"}]},{"ask":"為什麼不能直接把 h = 0 代進 (f(a + h) − f(a))/h？","options":[{"label":"h = 0 時 Q 和 P 重合，式子變成 0/0，沒有意義","correct":true},{"label":"因為 f(a) 可能不存在","why":"P 就在曲線上，f(a) 是存在的；問題出在分母 h = 0。"},{"label":"代進去會得到 0，答案太小","why":"代進去不是 0，是 0/0，根本不是一個數。"}]},{"ask":"某曲線在 (2, 5) 的切線斜率是 3。切線方程式是？","options":[{"label":"y = 3x − 1","correct":true},{"label":"y = 3x","why":"y = 3x 通過原點，不通過 (2, 5)。用點斜式 y − 5 = 3(x − 2)。"},{"label":"y = 3x + 5","why":"5 是切點的 y 座標，不是 y 截距。y − 5 = 3(x − 2) 整理成 y = 3x − 1。"}]},{"ask":"下面哪一句對？","options":[{"label":"切線可能在別的地方再和曲線相交","correct":true},{"label":"只和曲線碰一次的直線就是切線","why":"鉛直線 x = 1 只碰 y = x² 一次，但它不是切線；切線是用割線斜率的極限定義的。"},{"label":"每一條曲線在每一點都有切線","why":"|x| 在 0：右邊割線斜率都是 1、左邊都是 −1，極限不存在，沒有切線。"}]}],"practice":[{"id":"gi-101","core":true},{"id":"tb-tan-001","core":true},{"id":"tb-tan-002","core":true},{"id":"gx-031","core":true},{"id":"lec-02-q1d","core":true},{"id":"tb-tan-006","note":"割線斜率要先有理化，見〈0/0：有理化〉。"},{"id":"db-tan-001","challenge":true,"note":"挑戰：(2 + h)⁴ 要用二項式展開。"}]},"derivative-definition":{"id":"derivative-definition","prerequisites":["secant-to-tangent","limit-one-sided","limit-rationalize"],"next":["derivative-from-definition"],"related":["continuity-definition","limit-exp-log-standard","squeeze-theorem"],"objectives":["寫出 f′(a) 的兩種極限寫法，並說出它是切線斜率、也是瞬間變化率。","用定義算出某一點的導數，包括瞬間速度。","看到 lim_{h→0} (f(a + h) − f(a))/h 這種極限，認得出它是哪個函數在哪一點的導數。","用左右極限判斷一個點不可微（例如 |x| 在 0）。"],"concept":[{"heading":"① 給切線斜率一個名字","body":["上一課的極限太常用了，給它一個名字：f 在 a 的導數，記作 f′(a)。極限存在時，說 f 在 a 可微。"],"tex":["f'(a)=\\lim_{h\\to0}\\frac{f(a+h)-f(a)}{h}"]},{"heading":"② 同一件事的另一種寫法","body":["令 x = a + h，h → 0 就是 x → a，分母 h 就是 x − a。所以 f′(a) 也可以寫成下面這樣。兩種寫法算出來一樣，哪個好化簡就用哪個。"],"tex":["f'(a)=\\lim_{x\\to a}\\frac{f(x)-f(a)}{x-a}"]},{"heading":"③ 三種讀法","body":["圖形上：f′(a) 是曲線在 (a, f(a)) 的切線斜率。","變化上：(f(a + h) − f(a))/h 是 [a, a + h] 上的平均變化率，h → 0 就是「在 a 這一瞬間」的變化率，叫瞬間變化率。位置對時間的瞬間變化率就是瞬間速度。","單位和平均變化率一樣：y 的單位 ÷ x 的單位。f′(a) 是一個數；f(a) 是高度，f′(a) 是斜率，兩者沒有關係。"]},{"heading":"④ 什麼時候不可微","body":["導數是一個極限，極限可能不存在。常見的三種：尖角（|x| 在 0，左右極限分別是 −1 與 1）；鉛直切線（∛x 在 0，割線斜率 h^{1/3}/h = 1/h^{2/3} → ∞）；不連續（函數在 a 跳開，割線斜率會爆掉）。","所以「連續」不保證「可微」：|x| 在 0 連續，但不可微。反過來是對的：可微一定連續（下面的證明）。"]},{"heading":"可微一定連續（證明）","body":["設 f′(a) 存在。h ≠ 0 時，f(a + h) − f(a) = ((f(a + h) − f(a))/h) · h。","h → 0 時，右邊第一個因子 → f′(a)（假設），第二個因子 → 0。兩個極限都存在，乘積的極限等於極限的乘積：f′(a) · 0 = 0。","所以 lim_{h→0} f(a + h) = f(a)，這正是 f 在 a 連續的定義（〈連續的定義〉）。"],"collapsible":true}],"workedExamples":[{"title":"瞬間速度","prompt":"石頭 t 秒後的高度 h(t) = 80 − 4.9t²（公尺）。求 t = 2 時的瞬間速度。","problemId":"lx-app-001","steps":["函數名字已經用了 h，所以用 x → a 的寫法：h′(2) = lim_{t→2} (h(t) − h(2))/(t − 2)。","分子：h(t) − h(2) = (80 − 4.9t²) − (80 − 4.9 · 4) = −4.9(t² − 4) = −4.9(t − 2)(t + 2)。","除以 t − 2（t ≠ 2）：−4.9(t + 2)。","t → 2：−4.9 · 4 = −19.6。"],"answer":"−19.6 公尺／秒","note":"前 2 秒的平均速度是 −9.8，第 2 秒那一瞬間是它的兩倍：越掉越快。"},{"title":"認出極限是哪個導數","prompt":"lim_{h→0} (√(9 + h) − 3)/h","problemId":"dd-def-001","steps":["3 = √9，所以式子是 (√(9 + h) − √9)/h：f(x) = √x、a = 9 的導數定義。","算它：乘共軛 √(9 + h) + 3，分子變成 (9 + h) − 9 = h。","約掉 h（h ≠ 0）：1/(√(9 + h) + 3)。","h → 0：1/(3 + 3) = 1/6。所以 √x 在 x = 9 的切線斜率是 1/6。"],"answer":"1/6"},{"title":"|x| 在 0 不可微","prompt":"f(x) = |x|，f′(0) 存在嗎？","steps":["差商：(f(0 + h) − f(0))/h = |h|/h。","h > 0：|h| = h，差商是 1，右極限是 1。","h < 0：|h| = −h，差商是 −1，左極限是 −1。","左右極限不相等，極限不存在，f′(0) 不存在。"],"answer":"不存在（左右極限 −1 與 1）"}],"pitfalls":["把 f′(a) 和 f(a) 搞混：一個是斜率，一個是高度。","以為連續就一定可微。|x| 在 0 是反例。","x → a 的寫法分母寫成 a − x，答案差一個負號。","分子寫成 f(a + h) − f(h)，或 f(a) + h。","左右只算一邊，就說導數存在。"],"figures":[{"caption":"放大到 (1, 1)，x² 越看越像直線","after":0,"widget":{"type":"zoom","curves":[{"expr":"x^2","color":"blue"}],"center":[1,1],"window":[-1,3,-1,3],"levels":2}},{"caption":"|x| 放大多少倍都是尖角","after":3,"widget":{"type":"zoom","curves":[{"expr":"abs(x)","color":"blue"}],"center":[0,0],"window":[-2,2,-0.5,2],"levels":3}}],"checks":[{"ask":"lim_{h→0} ((2 + h)³ − 8)/h 是哪個導數？","options":[{"label":"f(x) = x³ 在 x = 2 的導數","correct":true},{"label":"f(x) = x³ − 8 在 x = 0 的導數","why":"那會是 ((0 + h)³ − 8 − (0 − 8))/h = h³/h，跟題目不同。8 = 2³ 告訴你 a = 2。"},{"label":"f(x) = (2 + x)³ 在 x = 2 的導數","why":"對 (2 + x)³ 在 x = 2，分子要是 (4 + h)³ − 64。這裡 2 + h 整個是輸入。"}]},{"ask":"f(3) = 5、f′(3) = −2。下面哪一句對？","options":[{"label":"曲線過 (3, 5)，那裡的切線斜率是 −2","correct":true},{"label":"曲線過 (3, −2)","why":"−2 是斜率，不是高度；高度是 f(3) = 5。"},{"label":"f 在 x = 3 附近遞增","why":"斜率是負的，表示在那一點往下走。"}]},{"ask":"f(x) = |x − 1|。f′(1)：","options":[{"label":"不存在","correct":true},{"label":"0","why":"尖角的底部看起來平，但差商 |h|/h 右邊是 1、左邊是 −1，極限不存在。"},{"label":"1","why":"那只是右極限；左極限是 −1，兩邊不等。"}]},{"ask":"下面哪一句對？","options":[{"label":"f 在 a 可微，則 f 在 a 連續","correct":true},{"label":"f 在 a 連續，則 f 在 a 可微","why":"|x| 在 0 連續但有尖角，不可微。"},{"label":"f 在 a 不連續，也可能可微","why":"可微一定連續，所以不連續就一定不可微（上面的證明）。"}]}],"practice":[{"id":"lx-app-001","core":true},{"id":"db-def-001","core":true},{"id":"dd-def-001","core":true},{"id":"lec-02-m3","core":true},{"id":"dd-pw-001","note":"√(x²) = |x|；在 x = −3 附近它等於 −x。"},{"id":"lx-der-003","note":"x → a 的寫法；算值要用〈指數與對數標準極限〉的 ln(1 + u)/u → 1。"},{"id":"lec-02-q3b","challenge":true,"note":"挑戰：差商是 h sin(1/h)，要用〈夾擠定理〉。"}]},"derivative-from-definition":{"id":"derivative-from-definition","prerequisites":["derivative-definition","limit-factor","limit-rationalize","limit-algebra-other"],"next":["derivative-power-rules"],"related":[],"objectives":["把 f′(a) 的 a 換成 x，得到導函數 f′(x)，並認得 f′(x)、dy/dx、d/dx 三種記號。","用「寫差商 → 化簡出因子 h → 約掉 → h → 0」四步，算出 x²、x³、1/x、√x 的導函數。","看出這四個結果的共同規律。"],"concept":[{"heading":"① 從一個點到每一個點","body":["上一課每次只算一個點。如果把 a 換成變數 x，算出來的就不是一個數，而是一個新的函數：每個 x 對到那裡的切線斜率。它叫 f 的導函數，記作 f′(x)。","也寫成 dy/dx 或 d/dx f(x)。dy/dx 是「Δy/Δx 取極限」的記號，目前把它整個當成一個符號，不是分數。"],"tex":["f'(x)=\\lim_{h\\to0}\\frac{f(x+h)-f(x)}{h}"]},{"heading":"② 固定四步","body":["1. 寫出差商 (f(x + h) − f(x))/h。直接代 h = 0 一定是 0/0。","2. 化簡分子，讓它冒出一個因子 h。","3. 約掉 h（h ≠ 0 所以可以約）。","4. 讓 h → 0，這時 x 當成固定的數。","第 2 步是全部的功夫，用的就是〈0/0：因式分解〉、〈0/0：有理化〉、〈其他代數化簡〉的工具：多項式展開、分式通分、根號乘共軛。"]},{"heading":"③ 最簡單的一個：x²","body":["(x + h)² − x² = 2xh + h²，除以 h 得 2x + h，h → 0 得 2x。所以 (x²)′ = 2x。檢查一下：上一課 x² 在 x = 1 的斜率是 2，代進 2x 也是 2。"]},{"heading":"④ 四個結果，一個規律","body":["範例算出 (x³)′ = 3x²、(1/x)′ = −1/x²、(√x)′ = 1/(2√x)。把它們寫成次方：x² → 2x¹、x³ → 3x²、x^{−1} → −1·x^{−2}、x^{1/2} → (1/2)x^{−1/2}。","每一個都是「次方搬到前面、次方減 1」。下一課〈常數、冪次、線性〉把它變成公式，以後就不用每次算極限。","注意定義域：√x 的導函數只在 x > 0 有定義。在 x = 0 差商是 √h/h = 1/√h（只能 h > 0），會 → ∞。"]}],"workedExamples":[{"title":"x³：展開","prompt":"用定義求 f(x) = x³ 的導函數。","steps":["展開：(x + h)³ = x³ + 3x²h + 3xh² + h³。","分子：(x + h)³ − x³ = 3x²h + 3xh² + h³，每一項都有 h。","除以 h：3x² + 3xh + h²。","h → 0：後兩項 → 0，得 f′(x) = 3x²。"],"answer":"3x²"},{"title":"1/x：通分","prompt":"用定義求 g(x) = 1/x 的導函數（x ≠ 0）。","steps":["差商：(1/(x + h) − 1/x)/h。","分子通分：1/(x + h) − 1/x = (x − (x + h))/(x(x + h)) = −h/(x(x + h))。","除以 h：−1/(x(x + h))。","h → 0：−1/(x · x) = −1/x²。"],"answer":"−1/x²"},{"title":"√x：有理化","prompt":"用定義求 k(x) = √x 的導函數（x > 0）。","steps":["差商：(√(x + h) − √x)/h。根號相減，乘共軛 √(x + h) + √x。","分子：(√(x + h) − √x)(√(x + h) + √x) = (x + h) − x = h。","式子變成 h/(h(√(x + h) + √x)) = 1/(√(x + h) + √x)。","h → 0：1/(√x + √x) = 1/(2√x)。"],"answer":"1/(2√x)"}],"pitfalls":["(x + h)² 展開成 x² + h²，漏了 2xh。","通分時分子寫成 (x + h) − x，正負號反了。","還沒約掉 h 就讓 h → 0，又得到 0/0。","h → 0 時把 x 也當成會動的東西。x 是固定的。","把 dy/dx 當成分數，把 d 約掉。"],"checks":[{"ask":"用定義算 (x²)′，差商化簡到哪一步可以讓 h → 0？","options":[{"label":"2x + h","correct":true},{"label":"(2xh + h²)/h","why":"分母還有 h，這時代 h = 0 是 0/0。要先約掉 h。"},{"label":"((x + h)² − x²)/h","why":"這是原式，直接讓 h → 0 是 0/0。要先展開、約分。"}]},{"ask":"用定義算 1/x 的導函數，分子 1/(x + h) − 1/x 通分後是？","options":[{"label":"−h/(x(x + h))","correct":true},{"label":"h/(x(x + h))","why":"通分後分子是 x − (x + h) = −h，前面的負號不能丟。"},{"label":"1/h","why":"分數相減不能分母相減：1/(x + h) − 1/x 要通分到 x(x + h)。"}]},{"ask":"f(x) = √x 的導函數在 x = 9 的值是？","options":[{"label":"1/6","correct":true},{"label":"1/3","why":"f′(x) = 1/(2√x)，分母的 2 不能漏：1/(2 · 3) = 1/6。"},{"label":"3","why":"3 是 f(9)，是高度不是斜率。"}]},{"ask":"f(x) = 1/x，f′(−1) 是？","options":[{"label":"−1","correct":true},{"label":"1","why":"f′(x) = −1/x²，x² 是正的，所以 f′ 永遠是負的：−1/(−1)² = −1。"},{"label":"不存在","why":"1/x 只在 x = 0 沒有定義；x = −1 時 f′(−1) = −1/1 = −1。"}]}],"practice":[{"id":"db-def-001","core":true},{"id":"lec-02-q1b","core":true},{"id":"lec-02-q1c","core":true},{"id":"lx-der-001","core":true},{"id":"lx-der-002"},{"id":"dd-def-002","challenge":true,"note":"挑戰：(2 + h)¹⁰ 不要全部展開，只要找出 h 一次方那一項。"}]},"derivative-power-rules":{"id":"derivative-power-rules","prerequisites":["derivative-from-definition"],"next":["derivative-trig"],"related":["product-rule","quotient-rule","logarithmic-differentiation","limit-laws-direct"],"objectives":["用冪次法則 (xⁿ)′ = nxⁿ⁻¹ 微分任何次方，包括負數與分數次方。","用常數倍與加減的規則，一項一項微分多項式。","先把 1/x³、√x、(x² + 1)/x 改寫成次方的和，再微分。"],"concept":[{"heading":"① 常數與 x","body":["常數函數 f(x) = c 的圖形是水平線，每一點斜率都是 0：(c)′ = 0。用定義：(c − c)/h = 0。","f(x) = x 的圖形是斜率 1 的直線：(x)′ = 1。用定義：((x + h) − x)/h = 1。"]},{"heading":"② 冪次法則","body":["上一課算出 x² → 2x、x³ → 3x²、x^{−1} → −x^{−2}、x^{1/2} → (1/2)x^{−1/2}。規律是：次方搬到前面當係數，次方減 1。","這對任何實數次方 n 都成立（n 不是整數時要 x > 0）。正整數的證明在下面；負整數可以用〈除法法則〉證，任意實數次方在〈對數微分〉證。"],"tex":["\\frac{d}{dx}x^n=n\\,x^{n-1}"]},{"heading":"③ 線性：常數倍與加減","body":["(c·f)′ = c·f′：常數倍留著不動。(f ± g)′ = f′ ± g′：加減可以一項一項微。","原因是差商也能這樣拆：(c·f(x + h) − c·f(x))/h = c·(f(x + h) − f(x))/h，取極限時常數提出來（極限定律，〈直接代入與極限定律〉）。","所以多項式可以逐項微分：(x⁵ − 3x² + 7)′ = 5x⁴ − 6x + 0。"]},{"heading":"④ 先改寫成次方，再微分","body":["冪次法則只認 xⁿ 的樣子，所以先改寫：1/x³ = x^{−3}，√x = x^{1/2}，∛(x²) = x^{2/3}，(x² + 1)/x = x + x^{−1}。","但乘法、除法不能逐項拆：(x² · x³)′ 不是 2x · 3x²。能展開或約分就先化成次方的和；不能的，要等〈乘法法則〉與〈除法法則〉。"]},{"heading":"正整數 n 的證明","body":["由二項式定理，(x + h)ⁿ = xⁿ + n xⁿ⁻¹ h + C(n, 2) xⁿ⁻² h² + … + hⁿ。","減掉 xⁿ，剩下的每一項至少有一個 h；除以 h（h ≠ 0）：n xⁿ⁻¹ + C(n, 2) xⁿ⁻² h + … + hⁿ⁻¹。","第一項不含 h；其餘每一項都含 h 的一次方以上，是有限多項，h → 0 時各自 → 0。所以極限是 n xⁿ⁻¹。"],"collapsible":true}],"workedExamples":[{"title":"多項式逐項微分","prompt":"d/dx (x⁵ − 3x² + 7)","problemId":"der-001","steps":["加減逐項：x⁵、−3x²、7 各自微分。","(x⁵)′ = 5x⁴。","(−3x²)′ = −3 · 2x = −6x（常數倍留著）。","(7)′ = 0。合起來 5x⁴ − 6x。"],"answer":"5x⁴ − 6x"},{"title":"負次方與分數次方","prompt":"d/dx (2/x³ + 4√x)","steps":["改寫：2/x³ = 2x^{−3}，4√x = 4x^{1/2}。","(2x^{−3})′ = 2 · (−3)x^{−4} = −6x^{−4}。次方是 −3 − 1 = −4，不是 −2。","(4x^{1/2})′ = 4 · (1/2)x^{−1/2} = 2x^{−1/2}。","寫回分式：−6/x⁴ + 2/√x（x > 0）。"],"answer":"−6/x⁴ + 2/√x"},{"title":"先約分，再求切線斜率","prompt":"f(x) = (x² + 1)/x，求 f′(2)。","steps":["分子分母不能各自微分。先拆開：(x² + 1)/x = x + 1/x = x + x^{−1}。","f′(x) = 1 + (−1)x^{−2} = 1 − 1/x²。","f′(2) = 1 − 1/4 = 3/4。"],"answer":"3/4"}],"pitfalls":["(1/x³)′ 寫成 1/(3x²)：要先改成 x^{−3}，得 −3x^{−4}。","負次方減 1 往錯的方向：x^{−3} 的次方減 1 是 −4。","常數的導數寫成常數本身，例如 (7)′ = 7、(π²)′ = 2π。","分式的分子分母各自微分：((x² + 1)/x)′ 寫成 2x/1。","√x 微分成 √x/2 或 1/√x，漏了 1/2 或次方減 1。"],"checks":[{"ask":"d/dx (4x³) 是？","options":[{"label":"12x²","correct":true},{"label":"4x²","why":"次方 3 要搬到前面乘：4 · 3 = 12。"},{"label":"12x³","why":"次方要減 1：x³ 微分後是 x²。"}]},{"ask":"d/dx (1/x²) 是？","options":[{"label":"−2/x³","correct":true},{"label":"1/(2x)","why":"把分母當成 x² 去微分是錯的。先改寫 x^{−2}，得 −2x^{−3}。"},{"label":"−2/x","why":"x^{−2} 的次方減 1 是 −3，不是 −1。"}]},{"ask":"d/dx (π³ + x) 是？","options":[{"label":"1","correct":true},{"label":"3π² + 1","why":"π³ 是常數（約 31），不是 x 的函數，導數是 0。"},{"label":"π³","why":"常數的導數是 0，不是它自己；x 的導數才是 1。"}]},{"ask":"f(x) = x√x，f′(x) 是？","options":[{"label":"(3/2)√x","correct":true},{"label":"1/(2√x)","why":"只微了 √x，x 那個因子不能丟。先合併 x · x^{1/2} = x^{3/2}。"},{"label":"(3/2)x^{3/2}","why":"次方搬到前面之後要減 1：3/2 − 1 = 1/2，得 (3/2)x^{1/2}。"}]}],"practice":[{"id":"tmpl-der-simple-power-001","core":true},{"id":"fd-der-002","core":true},{"id":"der-001","core":true},{"id":"der-004","core":true},{"id":"fd-der-010","core":true},{"id":"cx-der-001","core":true},{"id":"tb-tan-002"},{"id":"rel-basic-010"},{"id":"td-der-002"},{"id":"db-tan-001"}]},"derivative-trig":{"id":"derivative-trig","prerequisites":["derivative-power-rules","limit-trig-standard","trig-identities"],"next":["derivative-exp"],"related":["chain-rule","quotient-rule"],"objectives":["背熟六個三角函數的導數，並用「co 開頭的帶負號」記正負。","說出這些公式只在弧度下成立的原因。","算三角函數在某一點的切線斜率，以及認出 lim (sin(a + h) − sin a)/h 是哪個導數。"],"concept":[{"heading":"① 從圖看 (sin x)′ = cos x（直覺，不是證明）","body":["看 sin x 的圖：x = 0 時曲線以斜率 1 往上爬；x = π/2 在山頂，斜率 0；x = π 往下穿過 x 軸，斜率 −1；x = 3π/2 在谷底，斜率 0。","把這些斜率點出來：1、0、−1、0……正好是 cos x 在這些點的值。這只是抽樣幾個點，沒有說明中間每一點都對得上；真正的證明在下面。"]},{"heading":"② 六個公式","body":["記法：sin、tan、sec 的導數都是正的；co 開頭的 cos、cot、csc，導數前面都有負號，而且長相是把前三個的答案「每個字都換成 co 版本」：sec² ↔ csc²，sec·tan ↔ csc·cot。"],"tex":["(\\sin x)'=\\cos x,\\qquad (\\cos x)'=-\\sin x","(\\tan x)'=\\sec^2 x,\\qquad (\\cot x)'=-\\csc^2 x","(\\sec x)'=\\sec x\\tan x,\\qquad (\\csc x)'=-\\csc x\\cot x"]},{"heading":"③ 只在弧度下成立","body":["證明的關鍵是 lim_{h→0} sin h/h = 1（〈三角標準極限〉），而這個極限只在 h 用弧度量的時候是 1。","如果 x 用度，sin(x°) = sin(πx/180)，導數會多一個因子 π/180（要用〈連鎖律 I：兩層〉）。所以微積分裡的三角函數一律用弧度。"]},{"heading":"④ 公式本身就是極限","body":["lim_{h→0} (sin(π/6 + h) − 1/2)/h 看起來很難，其實 1/2 = sin(π/6)，這就是 sin x 在 π/6 的導數 = cos(π/6) = √3/2。認出導數定義，就不用硬算。"]},{"heading":"sin 與 cos 的證明","body":["需要兩個極限（〈三角標準極限〉）：sin h/h → 1，以及 (1 − cos h)/h² → 1/2。由後者，(cos h − 1)/h = −((1 − cos h)/h²) · h → −(1/2) · 0 = 0。","和角公式：sin(x + h) = sin x cos h + cos x sin h。所以 (sin(x + h) − sin x)/h = sin x · (cos h − 1)/h + cos x · (sin h/h)。","x 固定，h → 0：sin x · 0 + cos x · 1 = cos x。","同理 cos(x + h) = cos x cos h − sin x sin h，(cos(x + h) − cos x)/h = cos x · (cos h − 1)/h − sin x · (sin h/h) → cos x · 0 − sin x · 1 = −sin x。"],"collapsible":true},{"heading":"tan 與 sec 的證明（cos x ≠ 0 的地方）","body":["tan(x + h) − tan x = (sin(x + h)cos x − cos(x + h)sin x)/(cos(x + h)cos x) = sin h/(cos(x + h)cos x)，分子用的是 sin 的差角公式 sin((x + h) − x)。","除以 h：(sin h/h) · 1/(cos(x + h)cos x)。cos 連續，h → 0 時 cos(x + h) → cos x ≠ 0，所以極限是 1 · 1/cos² x = sec² x。","sec(x + h) − sec x = (cos x − cos(x + h))/(cos(x + h)cos x)。除以 h，分子部分 (cos x − cos(x + h))/h → −(cos x)′ = sin x，分母 → cos² x，所以極限是 sin x/cos² x = sec x tan x。","cot 與 csc 完全對稱（把 sin、cos 互換並注意正負），之後也可以用〈除法法則〉一行算出來。"],"collapsible":true}],"workedExamples":[{"title":"逐項微分","prompt":"d/dx (sin x + cos x)","problemId":"der-002","steps":["加減可以逐項微分。","(sin x)′ = cos x。","(cos x)′ = −sin x，負號不能漏。","合起來 cos x − sin x。"],"answer":"cos x − sin x"},{"title":"tan x 在 π/4 的切線","prompt":"求 y = tan x 在 x = π/4 的切線斜率與切線方程式。","problemId":"tb-tan-004","steps":["(tan x)′ = sec² x = 1/cos² x。","cos(π/4) = √2/2，cos²(π/4) = 1/2，所以斜率 = 1/(1/2) = 2。","切點：tan(π/4) = 1，切點是 (π/4, 1)。","切線：y − 1 = 2(x − π/4)，即 y = 2x + 1 − π/2。"],"answer":"斜率 2；y = 2x + 1 − π/2"},{"title":"sec 與 cot 混在一起","prompt":"f(x) = 2 sec x + cot x，求 f′(π/3)。","steps":["f′(x) = 2 sec x tan x − csc² x。","x = π/3：cos = 1/2，所以 sec = 2；tan = √3；sin = √3/2，所以 csc = 2/√3，csc² = 4/3。","f′(π/3) = 2 · 2 · √3 − 4/3 = 4√3 − 4/3。"],"answer":"4√3 − 4/3"}],"pitfalls":["(cos x)′ 寫成 sin x，漏了負號。","(tan x)′ 寫成 sec x，漏了平方。","計算機或心算用度：x 是 30 而不是 π/6。","把 sec x 的導數記成 tan x，或記成 sec² x（那是 tan 的）。","sin 2x 直接寫成 cos 2x；裡面不是單純的 x 時要用〈連鎖律 I：兩層〉。"],"checks":[{"ask":"d/dx (3 sin x − 2 cos x) 是？","options":[{"label":"3 cos x + 2 sin x","correct":true},{"label":"3 cos x − 2 sin x","why":"(cos x)′ = −sin x，所以 −2 cos x 微分是 −2 · (−sin x) = +2 sin x。"},{"label":"−3 cos x − 2 sin x","why":"(sin x)′ = cos x 沒有負號；負號只跟著 co 開頭的函數。"}]},{"ask":"下面哪一個導數前面有負號？","options":[{"label":"(csc x)′","correct":true},{"label":"(sec x)′","why":"(sec x)′ = sec x tan x，是正的；有負號的是 co 開頭的 cos、cot、csc。"},{"label":"(tan x)′","why":"(tan x)′ = sec² x，是正的。"}]},{"ask":"lim_{h→0} (cos(π/3 + h) − 1/2)/h 是？","options":[{"label":"−√3/2","correct":true},{"label":"√3/2","why":"這是 cos x 在 π/3 的導數，(cos x)′ = −sin x，負號不能漏：−sin(π/3) = −√3/2。"},{"label":"0","why":"0/0 不是 0。1/2 = cos(π/3)，所以這是 cos 在 π/3 的導數。"}]},{"ask":"為什麼 (sin x)′ = cos x 要用弧度？","options":[{"label":"證明用到 sin h/h → 1，這只在弧度下成立","correct":true},{"label":"因為度不能代進 sin","why":"度可以代進 sin（sin 30° = 1/2）；問題是用度時 sin h/h 的極限是 π/180，不是 1。"},{"label":"其實用度也一樣","why":"用度的話 (sin x°)′ = (π/180) cos x°，多一個因子。"}]}],"practice":[{"id":"rel-basic-008","core":true},{"id":"fd-der-008","core":true},{"id":"der-002","core":true},{"id":"cx-der-006","core":true},{"id":"tb-tan-004","core":true},{"id":"dd-def-003","core":true},{"id":"db-def-002"},{"id":"dd-def-004"},{"id":"gi-102"},{"id":"db-def-008","challenge":true,"note":"挑戰：x → a 的寫法，先認出 1 = tan(π/4)。"}]},"derivative-exp":{"id":"derivative-exp","prerequisites":["derivative-power-rules","exp-log","limit-exp-log-standard"],"next":["derivative-log"],"related":["chain-rule","logarithmic-differentiation"],"objectives":["說出為什麼指數函數的斜率跟自己的高度成正比。","用 (eˣ)′ = eˣ 與 (aˣ)′ = aˣ ln a 微分並求切線。","分清楚 aˣ（指數）和 xᵃ（冪次）用的是不同公式。"],"concept":[{"heading":"① 斜率跟高度成正比","body":["用定義算 f(x) = aˣ（a > 0）：a^{x+h} = aˣ · aʰ，所以差商是 aˣ · (aʰ − 1)/h。","aˣ 跟 h 無關，可以提出來；剩下的 (aʰ − 1)/h 跟 x 無關。所以 (aˣ)′ = aˣ · k，k 是 (aʰ − 1)/h 在 h → 0 的極限，一個只跟底數 a 有關的常數。","圖形的意思：曲線越高，斜率越大，而且「斜率 ÷ 高度」處處相同。x = 0 時高度是 1，所以 k 就是曲線在 x = 0 的斜率。"]},{"heading":"② e 是讓 k 剛好等於 1 的底數","body":["數值上，h = 0.0001 時 (2ʰ − 1)/h ≈ 0.6932、(3ʰ − 1)/h ≈ 1.0987。底數從 2 到 3，k 從比 1 小變得比 1 大，中間有一個底數讓 k = 1，就是 e ≈ 2.718：lim_{h→0} (eʰ − 1)/h = 1（〈指數與對數標準極限〉）。","所以 eˣ 的導數就是它自己：每一點的斜率等於那一點的高度。這是微積分偏愛 e 的原因。"],"tex":["(e^x)'=e^x"]},{"heading":"③ 一般底數","body":["對一般的 a > 0，k = ln a（證明在下面）。2 的 k ≈ 0.6932 正是 ln 2。","0 < a < 1 時 ln a < 0，斜率是負的，aˣ 遞減，跟 (1/2)ˣ 的圖一致。a = 1 時 1ˣ = 1 是常數，公式給 1 · ln 1 = 0，也對。"],"tex":["(a^x)'=a^x\\ln a"]},{"heading":"④ aˣ 不是 xᵃ","body":["x² 是冪次（底數在變），用冪次法則得 2x；2ˣ 是指數（次方在變），得 2ˣ ln 2。兩個混用是最常見的錯。底數和次方都在變的 xˣ 兩個公式都不能用，要等〈對數微分〉。"]},{"heading":"(aʰ − 1)/h → ln a 的證明","body":["a = 1 時兩邊都是 0。以下設 a ≠ 1，所以 ln a ≠ 0。","aʰ = e^{h ln a}。令 u = h ln a：h → 0 時 u → 0，而且 h ≠ 0 時 u ≠ 0。","(aʰ − 1)/h = (eᵘ − 1)/(u/ln a) = ln a · (eᵘ − 1)/u。","u → 0 時 (eᵘ − 1)/u → 1（〈指數與對數標準極限〉），所以極限是 ln a。"],"collapsible":true}],"workedExamples":[{"title":"eˣ 與多項式混在一起","prompt":"f(x) = 3eˣ − x²，求 f′(x) 與 f′(0)。","steps":["逐項：(3eˣ)′ = 3eˣ（常數倍留著），(x²)′ = 2x。","f′(x) = 3eˣ − 2x。","f′(0) = 3 · 1 − 0 = 3。"],"answer":"f′(x) = 3eˣ − 2x；f′(0) = 3"},{"title":"底數 2","prompt":"d/dx 2ˣ，以及它在 x = 3 的值。","problemId":"lec-03-m5","steps":["次方在變，是指數函數：(2ˣ)′ = 2ˣ ln 2。","x = 3：2³ ln 2 = 8 ln 2 ≈ 5.545。"],"answer":"2ˣ ln 2；8 ln 2"},{"title":"eˣ 在 x = 1 的切線過原點","prompt":"求 y = eˣ 在 x = 1 的切線方程式。","steps":["斜率：(eˣ)′ 在 x = 1 是 e。","切點：(1, e)。","y − e = e(x − 1)，整理得 y = ex。","常數項剛好消掉，這條切線通過原點。"],"answer":"y = ex"}],"pitfalls":["用冪次法則微分 eˣ，寫成 x e^{x−1}。","(2ˣ)′ 寫成 2ˣ，漏了 ln 2；或寫成 x · 2^{x−1}。","(e²)′ 寫成 e²。e² 是常數，導數是 0。","(eˣ)′ = eˣ 是對的，但 e^{3x} 直接寫成 e^{3x}；裡面不是單純的 x 要用〈連鎖律 I：兩層〉。"],"checks":[{"ask":"d/dx (5ˣ) 是？","options":[{"label":"5ˣ ln 5","correct":true},{"label":"x · 5^{x−1}","why":"那是把 5ˣ 當冪次用冪次法則；這裡變的是次方，要用 (aˣ)′ = aˣ ln a。"},{"label":"5ˣ","why":"只有底數是 e 時導數才等於自己；底數 5 要多乘 ln 5。"}]},{"ask":"d/dx (eˣ + eᵉ) 是？","options":[{"label":"eˣ","correct":true},{"label":"eˣ + eᵉ","why":"eᵉ 是一個常數（約 15.15），導數是 0。"},{"label":"eˣ + e · e^{e−1}","why":"eᵉ 裡面沒有 x，不能用冪次法則，它是常數。"}]},{"ask":"y = (1/2)ˣ 的導數在每一點都是？","options":[{"label":"負的","correct":true},{"label":"正的","why":"(1/2)ˣ 的導數是 (1/2)ˣ ln(1/2)，ln(1/2) = −ln 2 < 0，所以是負的，函數遞減。"},{"label":"0","why":"(1/2)ˣ 不是常數；只有底數 1 才會導數處處為 0。"}]},{"ask":"eˣ 在 x = 2 的切線斜率是？","options":[{"label":"e²","correct":true},{"label":"2e","why":"那是 x · e^{x−1} 之類的冪次法則結果；(eˣ)′ = eˣ，代 2 得 e²。"},{"label":"1","why":"斜率 1 是 x = 0 的時候；x = 2 時斜率等於高度 e²。"}]}],"practice":[{"id":"lec-03-m5","core":true},{"id":"gx-032","core":true},{"id":"gi-103","core":true},{"id":"db-def-004","challenge":true,"note":"挑戰：拆成 (e^{3h} − 1)/h − (e^{−2h} − 1)/h，各自用標準極限。"}]},"derivative-log":{"id":"derivative-log","prerequisites":["derivative-exp","exp-log","inverse-function","limit-exp-log-standard"],"next":["product-rule"],"related":["inverse-trig-derivative","chain-rule","logarithmic-differentiation"],"objectives":["用 (ln x)′ = 1/x 與 (logₐ x)′ = 1/(x ln a) 微分並求切線。","先用對數律把 ln(x³)、ln(5x)、log₂(x³) 拆開再微分。","知道 (ln|x|)′ = 1/x 對所有 x ≠ 0 成立。"],"concept":[{"heading":"① 鏡子裡的斜率（直覺，不是證明）","body":["ln x 是 eˣ 的反函數，兩個圖形對稱於 y = x（〈反函數〉）。在 eˣ 上的點 (a, eᵃ)，切線斜率是 eᵃ。","對 y = x 翻過去，點變成 (eᵃ, a)，直線的水平變化和鉛直變化對調，斜率變成倒數 1/eᵃ。這個點的 x 座標正是 eᵃ，所以 ln x 在 x 的斜率是 1/x。","這個論證先假設了 ln x 可微；嚴格的算法在下面，用的是導數定義。"]},{"heading":"② 公式","body":["ln x 只在 x > 0 有定義，所以這個公式也是 x > 0。x = 1 時斜率 1；x = 100 時斜率 0.01：ln x 一直往上，但越爬越慢。","其他底數用換底：logₐ x = ln x / ln a，ln a 是常數，所以導數是 1/(x ln a)。"],"tex":["(\\ln x)'=\\frac1x\\quad(x>0),\\qquad (\\log_a x)'=\\frac{1}{x\\ln a}"]},{"heading":"③ 先拆再微","body":["對數律可以把乘、除、次方變成加、減、乘：ln(x³) = 3 ln x，導數 3/x。ln(5x) = ln 5 + ln x，ln 5 是常數，所以導數是 1/x，跟 ln x 一樣：圖形只是整條往上平移 ln 5。","ln(x² + 1) 拆不開（ln 不能拆加法），要用〈連鎖律 I：兩層〉。"]},{"heading":"④ ln|x|：負數那一半","body":["ln|x| 在 x < 0 也有定義，圖形是 ln x 對 y 軸的鏡像。左右鏡射會把斜率變號，而 x 本身也變號，結果公式不變：對所有 x ≠ 0，(ln|x|)′ = 1/x。積分時會再用到它。"]},{"heading":"用定義證明 (ln x)′ = 1/x 與 (ln|x|)′ = 1/x","body":["固定 x > 0。差商：(ln(x + h) − ln x)/h = ln((x + h)/x)/h = ln(1 + h/x)/h。","令 u = h/x：h → 0 時 u → 0，h ≠ 0 時 u ≠ 0，而且 h = xu。差商 = ln(1 + u)/(xu) = (1/x) · ln(1 + u)/u。","ln(1 + u)/u → 1（〈指數與對數標準極限〉），所以極限是 1/x。","x < 0 時，ln|x| = ln(−x)。記 v = −x > 0，差商 (ln(−x − h) − ln(−x))/h = −(ln(v + (−h)) − ln v)/(−h)。h → 0 時 −h → 0，後面那個分式是 ln 在 v 的差商，→ 1/v。所以極限是 −1/v = −1/(−x) = 1/x。"],"collapsible":true}],"workedExamples":[{"title":"切線的 y 截距","prompt":"y = ln x 在 x = e² 的切線，y 截距是多少？","problemId":"db-tan-003","steps":["斜率：1/x 在 x = e² 是 1/e²。","切點：ln(e²) = 2，切點是 (e², 2)。","切線：y − 2 = (1/e²)(x − e²) = x/e² − 1，所以 y = x/e² + 1。","令 x = 0，y 截距是 1。"],"answer":"1"},{"title":"先用對數律","prompt":"y = log₂(x³)（x > 0），求 y′。","problemId":"lec-03-q2d","steps":["對數律：log₂(x³) = 3 log₂ x。","(log₂ x)′ = 1/(x ln 2)。","y′ = 3/(x ln 2)。"],"answer":"3/(x ln 2)"},{"title":"ln|x| 在負數","prompt":"y = ln|x|，求 x = −2 處的切線斜率。","steps":["x ≠ 0 時 (ln|x|)′ = 1/x。","x = −2：1/(−2) = −1/2。","合理性：x < 0 那一半是 ln x 的左右鏡像，x 往右走時 |x| 變小，函數值下降，斜率應該是負的。"],"answer":"−1/2"}],"pitfalls":["(ln 5)′ 寫成 1/5。ln 5 是常數，導數是 0。","ln(x + 1) 拆成 ln x + ln 1。對數不能拆加法。","(log₂ x)′ 寫成 1/x，漏了 ln 2。","(ln(5x))′ 寫成 1/(5x)，或 5/x：拆成 ln 5 + ln x 就知道是 1/x。","在 x ≤ 0 的地方用 ln x 的導數，忘了 ln x 只在 x > 0 有定義。"],"checks":[{"ask":"d/dx ln(x⁴)（x > 0）是？","options":[{"label":"4/x","correct":true},{"label":"1/x⁴","why":"1/(裡面) 只對了一半：ln(x⁴) = 4 ln x，導數是 4/x。"},{"label":"4 ln x","why":"4 ln x 是 ln(x⁴) 改寫後的樣子，還沒微分。"}]},{"ask":"d/dx ln(7x) 是？","options":[{"label":"1/x","correct":true},{"label":"1/(7x)","why":"ln(7x) = ln 7 + ln x，ln 7 是常數，導數只剩 1/x。"},{"label":"7/x","why":"7 是乘在裡面，不是次方；拆開後是 ln 7 + ln x，不是 7 ln x。"}]},{"ask":"d/dx log₁₀ x 是？","options":[{"label":"1/(x ln 10)","correct":true},{"label":"1/x","why":"1/x 是 ln x（底數 e）的導數；底數 10 要多除 ln 10。"},{"label":"ln 10/x","why":"換底是 ln x / ln 10，ln 10 在分母，不是乘上去。"}]},{"ask":"y = ln|x| 在 x = −4 的切線斜率是？","options":[{"label":"−1/4","correct":true},{"label":"1/4","why":"(ln|x|)′ = 1/x，不是 1/|x|。x = −4 時是 −1/4；左半邊往右走是下降的。"},{"label":"不存在","why":"ln|x| 在 x = −4 有定義而且可微；只有 x = 0 不行。"}]}],"practice":[{"id":"rel-basic-011","core":true},{"id":"db-tan-003","core":true},{"id":"lec-03-q2d","core":true},{"id":"dd-def-005","core":true},{"id":"ch-trap-002","core":true,"note":"ln 和 e 互相抵消，先化簡就不用連鎖律。"},{"id":"lx-der-003"},{"id":"db-def-006"}]},"product-rule":{"id":"product-rule","prerequisites":["derivative-power-rules","derivative-trig","derivative-exp","derivative-log"],"next":["quotient-rule"],"related":["derivative-definition"],"objectives":["知道 (fg)′ 不是 f′g′，並能用 x · x 這個例子說出為什麼。","用 (fg)′ = f′g + fg′ 微分兩個函數相乘，三個相乘時也會用。","算出導函數之後，在指定的點代值求導數。"],"concept":[{"heading":"① 各自微分再相乘是錯的","body":["x · x = x²，導數是 2x。如果「各自微分再相乘」，會得到 1 · 1 = 1。兩個不一樣，所以相乘的函數要有自己的規則。","正確的規則從哪裡來？把乘積 f(x)g(x) 看成面積：面積變大來自兩件事——寬變長了（乘上原來的高），高變長了（乘上原來的寬）。下面把這兩塊畫出來。"]},{"heading":"② 圖像：長方形變大時，多出來的面積","body":["把 f(x)、g(x) 想成長方形的寬和高，面積就是 f(x)g(x)。x 往右走 h，寬多 Δf、高多 Δg。多出來的面積是三塊：Δf · g、f · Δg，和角落的 Δf · Δg。","除以 h：Δf/h → f′，Δg/h → g′；角落那塊是 Δf · (Δg/h)，Δf → 0、Δg/h → g′，乘起來 → 0。剩下 f′g + fg′。","這是直覺，不是證明：它把 f、g 當成正的長度，也默認了 Δf → 0（也就是 f 連續）。完整證明在下面。"]},{"heading":"③ 公式","body":["前微後不微，加上前不微後微。用 x · x 驗：1 · x + x · 1 = 2x，對了。","三個相乘就輪流微：每一項只微一個因式，其他兩個不動，所以有三項。"],"tex":["(fg)'=f'g+fg'","(fgh)'=f'gh+fg'h+fgh'"]},{"heading":"④ 什麼時候不用","body":["常數乘函數不必用：(3x²)′ = 6x。套乘法法則也對（常數的導數是 0，那一項消失），只是多寫。","多項式相乘，也可以先展開再微分；兩種做法答案一定一樣（範例 3）。"]},{"heading":"⑤ 證明（加一項、減一項）","body":["設 f、g 在 x 可微。分子加減同一項 f(x + h)g(x)：","f(x + h)g(x + h) − f(x)g(x) = f(x + h)[g(x + h) − g(x)] + g(x)[f(x + h) − f(x)]。","兩邊除以 h：第一項是 f(x + h) · (g(x + h) − g(x))/h，第二項是 g(x) · (f(x + h) − f(x))/h。","h → 0 時，(g(x + h) − g(x))/h → g′(x)，(f(x + h) − f(x))/h → f′(x)。還要 f(x + h) → f(x)：f 在 x 可微，所以 f(x + h) − f(x) = h · (f(x + h) − f(x))/h → 0 · f′(x) = 0，也就是 f 在 x 連續。","合起來得 (fg)′(x) = f(x)g′(x) + g(x)f′(x)。"],"collapsible":true}],"workedExamples":[{"title":"多項式乘指數","prompt":"d/dx (x eˣ)","problemId":"fd-der-009","steps":["x 和 eˣ 都含 x，是兩個函數相乘。令 f = x、g = eˣ。","f′ = 1，g′ = eˣ。","f′g + fg′ = 1 · eˣ + x · eˣ。","提出共同的 eˣ：(x + 1)eˣ。"],"answer":"(x + 1)eˣ"},{"title":"先求導函數，再代點","prompt":"d/dx (x² ln x) 在 x = 1 的值","problemId":"cx-der-004","steps":["f = x²、g = ln x，f′ = 2x、g′ = 1/x。","f′g + fg′ = 2x ln x + x² · (1/x) = 2x ln x + x（x > 0）。","代 x = 1：2 · 1 · ln 1 + 1 = 0 + 1 = 1。"],"answer":"1","note":"要先微分再代值。先代 x = 1 會得到常數 0，常數的導數是 0，錯的。"},{"title":"兩種做法對答案","prompt":"y = (x² + 1)(x³ − x)，求 y′","problemId":"lec-02-q2a","steps":["乘法法則：f = x² + 1、g = x³ − x，f′ = 2x、g′ = 3x² − 1。","f′g = 2x(x³ − x) = 2x⁴ − 2x²；fg′ = (x² + 1)(3x² − 1) = 3x⁴ − x² + 3x² − 1 = 3x⁴ + 2x² − 1。","相加：2x⁴ − 2x² + 3x⁴ + 2x² − 1 = 5x⁴ − 1。","對答案：先展開 (x² + 1)(x³ − x) = x⁵ − x³ + x³ − x = x⁵ − x，微分得 5x⁴ − 1，一樣。"],"answer":"5x⁴ − 1"}],"pitfalls":["把 (fg)′ 寫成 f′g′。","只寫了一半：x sin x 微分寫成 x cos x，漏掉 1 · sin x。","x ln x 的第二項 x · (1/x) 沒化簡成 1。","三個相乘只寫兩項。","先代值再微分，得到 0。"],"checks":[{"ask":"d/dx (x sin x) 是？","options":[{"label":"cos x","why":"這是各自微分再相乘：1 · cos x。相乘的導數不能這樣算，x · x 就是反例。"},{"label":"sin x + x cos x","correct":true},{"label":"x cos x","why":"只做了「前不微後微」那一半，還要加上「前微後不微」1 · sin x。"}]},{"ask":"d/dx (x² eˣ) 是？","options":[{"label":"(x² + 2x)eˣ","correct":true},{"label":"2x eˣ","why":"這只是 f′g，還要加上 fg′ = x² eˣ。"},{"label":"2x · eˣ · x² · eˣ","why":"把兩項乘起來了。乘法法則是兩項相加：2x eˣ + x² eˣ。"}]},{"ask":"f(x) = x ln x，f′(e) 是？","options":[{"label":"1/e","why":"這是各自微分再相乘：1 · (1/x)，代 e 得 1/e。"},{"label":"1","why":"只算了 f′g = ln x，代 e 得 1；還要加 fg′ = x · (1/x) = 1。"},{"label":"2","correct":true}]},{"ask":"(fgh)′ 用乘法法則展開，有幾項？","options":[{"label":"3 項","correct":true},{"label":"2 項","why":"兩項是兩個因式的情形。三個因式要輪流微，每一個都輪到一次。"},{"label":"1 項","why":"那是 f′g′h′，各自微分再相乘，跟兩個因式時一樣是錯的。"}]}],"practice":[{"id":"fd-der-009","core":true},{"id":"fd-der-005","core":true},{"id":"lec-02-q2a","core":true},{"id":"rel-basic-012","core":true},{"id":"cx-der-004","core":true},{"id":"lec-02-m2","core":true},{"id":"cx-exam-003","note":"e^{−x} 的導數是 −e^{−x}。"},{"id":"exam-der-005","challenge":true,"note":"挑戰：三個因式相乘，其中 e^{−x} 要用到 (e^{−x})′ = −e^{−x}。"}]},"quotient-rule":{"id":"quotient-rule","prerequisites":["product-rule","derivative-trig","derivative-log"],"next":["chain-rule"],"related":["derivative-definition","increasing-decreasing"],"objectives":["用 (f/g)′ = (f′g − fg′)/g² 微分兩個函數相除，分子的順序不寫反。","用除法法則推出 (tan x)′ = sec² x。","認得出不必用除法法則的情形：分母是常數、可以先化簡、可以改寫成負次方。"],"concept":[{"heading":"① 相除也不能各自微分","body":["x²/x = x（x ≠ 0），導數是 1。各自微分再相除會得到 2x/1 = 2x。不一樣，所以相除也要自己的規則。"]},{"heading":"② 公式","body":["唸法：分母乘分子的導數，減掉分子乘分母的導數，整個除以分母的平方。這裡 g(x) ≠ 0。","跟乘法法則最大的不同是中間是減號，所以順序不能換：分子的導數 f′ 那一項在前。換了順序，答案差一個負號。","用 1/x 驗：f = 1、g = x，(0 · x − 1 · 1)/x² = −1/x²。跟冪次法則 (x⁻¹)′ = −x⁻² 一樣。"],"tex":["\\left(\\frac{f}{g}\\right)'=\\frac{f'g-fg'}{g^2}"]},{"heading":"③ 用它得到 tan x 的導數","body":["tan x = sin x / cos x。f = sin x、g = cos x，f′ = cos x、g′ = −sin x。","(cos x · cos x − sin x · (−sin x))/cos² x = (cos² x + sin² x)/cos² x = 1/cos² x = sec² x（cos x ≠ 0）。"],"tex":["(\\tan x)'=\\sec^2 x"]},{"heading":"④ 先看看能不能不用","body":["分母是常數：(x³ + 4x)/2 就是 ½(x³ + 4x)，導數 ½(3x² + 4)。","分子是常數：3/x² = 3x⁻²，導數 −6x⁻³。","能約分就先約：(x² + x)/x = x + 1（x ≠ 0），導數 1。","硬套除法法則也會對，只是步驟多、出錯的地方多。"]},{"heading":"⑤ 證明（從定義，加一項、減一項）","body":["設 f、g 在 x 可微，g(x) ≠ 0。g 在 x 可微所以連續，h 夠小時 g(x + h) 也不是 0。","通分：f(x + h)/g(x + h) − f(x)/g(x) = [f(x + h)g(x) − f(x)g(x + h)] / [g(x + h)g(x)]。","分子加減 f(x)g(x)：[f(x + h) − f(x)]g(x) − f(x)[g(x + h) − g(x)]。","除以 h，h → 0：分子 → f′(x)g(x) − f(x)g′(x)；分母 g(x + h)g(x) → g(x)²（g 連續）。得證。","另一個常見的推法是把 q = f/g 寫成 f = qg 再用乘法法則，但那要先知道 q 可微，等於把要證的東西先假設了，只能當記憶法。"],"collapsible":true}],"workedExamples":[{"title":"最基本的一題","prompt":"d/dx x/(x + 1)","problemId":"cx-der-005","steps":["f = x、g = x + 1，f′ = 1、g′ = 1。","f′g − fg′ = 1 · (x + 1) − x · 1 = 1。","除以 g² = (x + 1)²。"],"answer":"1/(x + 1)²"},{"title":"對數在分子","prompt":"d/dx (ln x)/x","problemId":"exam-der-003","steps":["f = ln x、g = x，f′ = 1/x、g′ = 1。","f′g − fg′ = (1/x) · x − ln x · 1 = 1 − ln x。","除以 x²：(1 − ln x)/x²。"],"answer":"(1 − ln x)/x²","note":"x < e 時導數為正、x > e 時為負，所以 x = e 是 (ln x)/x 最大的地方；〈增減區間〉會正式講這件事。"},{"title":"分子分母都是多項式","prompt":"d/dx (x² + 1)/(x − 1)","problemId":"der-038","steps":["f = x² + 1、g = x − 1，f′ = 2x、g′ = 1。","f′g = 2x(x − 1) = 2x² − 2x；fg′ = x² + 1。","相減時括號要整個減：2x² − 2x − (x² + 1) = x² − 2x − 1。","除以 (x − 1)²。"],"answer":"(x² − 2x − 1)/(x − 1)²"}],"pitfalls":["分子順序寫反成 fg′ − f′g，答案差一個負號。","分母忘了平方。","減 fg′ 時沒加括號：2x(x − 1) − x² + 1，最後一項的正負號錯。","寫成 f′/g′。","分母是常數也套公式，平白多出出錯的機會。"],"checks":[{"ask":"d/dx x/(x + 2) 是？","options":[{"label":"2/(x + 2)²","correct":true},{"label":"−2/(x + 2)²","why":"分子順序寫反了：要 f′g − fg′ = 1 · (x + 2) − x · 1，f′ 那一項在前。"},{"label":"1","why":"這是 f′/g′ = 1/1，各自微分再相除，不是除法法則。"}]},{"ask":"用除法法則算 (1/x)′，得到？","options":[{"label":"1/x²","why":"順序反了：(f′g − fg′) = 0 · x − 1 · 1 = −1，不是 +1。"},{"label":"−1/x²","correct":true},{"label":"0","why":"這是 f′/g′ = 0/1。分子是常數不代表整個分式的導數是 0。"}]},{"ask":"下面哪一個最不需要用除法法則？","options":[{"label":"(x³ + 4x)/2","correct":true},{"label":"x/(x + 1)","why":"分母含 x，而且分子分母約不掉，要用除法法則（或改寫成 1 − 1/(x + 1)）。"},{"label":"(sin x)/x","why":"分母含 x，約不掉也改寫不了，要用除法法則。"}]},{"ask":"f(x) = eˣ/x，f′(1) 是？","options":[{"label":"e","why":"這是 f′/g′ = eˣ/1 代 1。"},{"label":"0","correct":true},{"label":"2e","why":"中間的減號寫成了加號：(e · 1 + e · 1)/1 = 2e。應該是 (eˣ · x − eˣ · 1)/x²，代 1 得 0。"}]}],"practice":[{"id":"cx-der-005","core":true},{"id":"lec-02-q2b","core":true},{"id":"tmpl-der-quotient-shift-001","core":true},{"id":"exam-der-003","core":true},{"id":"der-038","core":true},{"id":"cx-der-006","core":true},{"id":"exam-der-009","note":"化簡時用 sin² x + cos² x = 1。"},{"id":"exam-der-020"},{"id":"dd-kin-005","challenge":true,"note":"挑戰：位置函數的導數是速度，在 t = 2 代值。"}]},"chain-rule":{"id":"chain-rule","prerequisites":["function-composition","derivative-power-rules","derivative-trig","derivative-exp","derivative-log","product-rule"],"next":["chain-rule-nested"],"related":[],"objectives":["把一個函數拆成外層與裡層：找「最後一步做的運算」。","用 (f(g(x)))′ = f′(g(x)) · g′(x) 微分兩層的合成函數。","分清楚 sin² x 與 sin(x²)、e^{x²} 與 e^{2x} 這幾對長得像的函數。"],"concept":[{"heading":"① 裡面不是單純的 x","body":["e^{2x} 不是 eˣ。直接套 (eˣ)′ = eˣ 會得到 e^{2x}，是錯的。","用已經會的方法算一次：e^{2x} = eˣ · eˣ，乘法法則給 eˣ · eˣ + eˣ · eˣ = 2e^{2x}。多出來的 2，正好是裡面 2x 的導數。"]},{"heading":"② 人話：變化率相乘","body":["寫成兩層：y = f(u)，u = g(x)。x 動一點點，u 大約動 g′(x) 倍；u 動一點點，y 大約動 f′(u) 倍。所以 x 動一點點，y 大約動 f′(u) · g′(x) 倍。","像齒輪：第一個齒輪轉一圈帶第二個轉 3 圈，第二個轉一圈帶第三個轉 2 圈，第一個轉一圈，第三個就轉 6 圈。"]},{"heading":"③ 公式","body":["外層照公式微分，裡面整包原封不動；再乘上裡層的導數。"],"tex":["\\frac{d}{dx}f(g(x))=f'(g(x))\\cdot g'(x)","\\frac{dy}{dx}=\\frac{dy}{du}\\cdot\\frac{du}{dx}"]},{"heading":"④ 怎麼拆外層、裡層","body":["想像拿計算機算這個函數，最後按的那個鍵就是外層。","(x² + 1)⁴：先算 x² + 1，最後四次方。外層 u⁴，裡層 x² + 1。","sin² x 是 (sin x)²：最後平方。外層 u²，裡層 sin x。","sin(x²)：最後取 sin。外層 sin u，裡層 x²。","如果裡層就是單純的 x，裡層導數是 1，連鎖律不改變任何事。"]},{"heading":"⑤ 直覺版的推導，以及它漏了什麼","body":["常見的推法：Δy/Δx = (Δy/Δu) · (Δu/Δx)，取極限得 dy/du · du/dx。這是直覺，不是證明：要除以 Δu，就得有 Δu ≠ 0。但有些函數在 x 附近 Δu 會一再等於 0（例如 g 是常數，或 g(x) = x² sin(1/x)、g(0) = 0 在 x = 0：h = 1/(nπ) 時 Δu = g(h) − g(0) = 0，這樣的 h 要多靠近 0 都有），這時這個寫法根本沒有定義。"],"collapsible":true},{"heading":"⑥ 證明（用輔助函數避開 Δu = 0）","body":["設 g 在 x 可微，f 在 a = g(x) 可微。定義 φ(k) = (f(a + k) − f(a))/k（k ≠ 0），φ(0) = f′(a)。因為 f 在 a 可微，k → 0 時 φ(k) → f′(a) = φ(0)，所以 φ 在 0 連續。","對每一個 k（包括 k = 0）都有 f(a + k) − f(a) = φ(k) · k：k ≠ 0 是 φ 的定義，k = 0 兩邊都是 0。","取 k = g(x + h) − g(x)，則 f(g(x + h)) − f(g(x)) = φ(k) · (g(x + h) − g(x))。除以 h（h ≠ 0）：","[f(g(x + h)) − f(g(x))]/h = φ(k) · (g(x + h) − g(x))/h。","h → 0：g 在 x 可微所以連續，k → 0；φ 在 0 連續，所以 φ(k) → φ(0) = f′(g(x))，就算某些 h 讓 k = 0 也沒關係。第二個因子 → g′(x)。相乘得 f′(g(x)) · g′(x)。"],"collapsible":true}],"workedExamples":[{"title":"外層是次方","prompt":"d/dx (x² + 1)⁴","problemId":"fd-der-006","steps":["最後一步是四次方。外層 u⁴，裡層 u = x² + 1。","外層微分：4u³ = 4(x² + 1)³，裡面原封不動。","裡層微分：(x² + 1)′ = 2x。","相乘：4(x² + 1)³ · 2x = 8x(x² + 1)³。"],"answer":"8x(x² + 1)³"},{"title":"外層是根號，再代點","prompt":"f(x) = √(3x + 1)，求 f′(1)","problemId":"cx-der-007","steps":["外層 √u，導數 1/(2√u)；裡層 u = 3x + 1，導數 3。","f′(x) = 1/(2√(3x + 1)) · 3 = 3/(2√(3x + 1))。","代 x = 1：√4 = 2，f′(1) = 3/(2 · 2) = 3/4。"],"answer":"3/4"},{"title":"sin² x：外層是平方","prompt":"d/dx sin² x","problemId":"der-039","steps":["sin² x = (sin x)²，最後一步是平方。外層 u²，裡層 u = sin x。","外層微分：2u = 2 sin x。","裡層微分：(sin x)′ = cos x。","相乘：2 sin x cos x（也可以寫成 sin 2x）。"],"answer":"2 sin x cos x","note":"比較 sin(x²)：外層 sin、裡層 x²，導數是 2x cos(x²)。兩個完全不同。"}],"pitfalls":["忘了乘裡層的導數：sin 2x 微分寫成 cos 2x。","外層微分時把裡面也換掉：(x² + 1)⁴ 寫成 4(2x)³。","把 sin² x 當成 sin(x²)。","把 e^{x²} 的導數寫成 e^{2x}，或 2x · e^{2x}。","裡層的導數乘到外層的裡面去：寫成 cos(2 · 2x)。"],"checks":[{"ask":"d/dx sin(5x) 是？","options":[{"label":"cos(5x)","why":"外層對了，但忘了乘裡層 5x 的導數 5。"},{"label":"5 cos x","why":"外層微分時把裡面換成了 x。裡面要原封不動留著 5x。"},{"label":"5 cos(5x)","correct":true}]},{"ask":"d/dx (x³ + 1)² 是？","options":[{"label":"6x²(x³ + 1)","correct":true},{"label":"2(x³ + 1)","why":"只做了外層，還要乘裡層 x³ + 1 的導數 3x²。"},{"label":"2(3x²)","why":"外層 u² 微分是 2u，u 要留原樣 x³ + 1，不是換成裡層的導數 3x²。"}]},{"ask":"d/dx sin² x 是？","options":[{"label":"2x cos(x²)","why":"這是 sin(x²) 的導數。sin² x 是 (sin x)²，外層是平方。"},{"label":"2 sin x cos x","correct":true},{"label":"2 sin x","why":"外層 u² 微分得 2u = 2 sin x 沒錯，但還要乘裡層 sin x 的導數 cos x。"}]},{"ask":"f(x) = e^{x²}，f′(1) 是？","options":[{"label":"e","why":"只做了外層 e^{x²}，忘了乘裡層 x² 的導數 2x。"},{"label":"e²","why":"把 e^{x²} 看成了 e^{2x}。f′(x) = 2x e^{x²}，代 1 得 2e。"},{"label":"2e","correct":true}]}],"practice":[{"id":"tmpl-der-sin-001","core":true},{"id":"fd-der-003","core":true},{"id":"fd-der-004","core":true},{"id":"fd-der-006","core":true},{"id":"fd-der-011","core":true},{"id":"lec-03-m2","core":true},{"id":"cx-der-007","core":true},{"id":"der-039","core":true},{"id":"cx-der-003"},{"id":"tmpl-der-chain-exp-001"},{"id":"db-chain-004"},{"id":"der-026","challenge":true,"note":"挑戰：外層是乘法，先用乘法法則；sin(3x) 那一項再用連鎖律。"}]},"chain-rule-nested":{"id":"chain-rule-nested","prerequisites":["chain-rule","product-rule","quotient-rule"],"next":["implicit-differentiation"],"related":[],"objectives":["把三層以上的合成函數一層一層拆開，每一層乘一個導數，不漏層。","混合題先判斷最外面是乘、除還是合成，決定第一步用哪條法則。","數對 sin³(2x) 這類寫法的層數。"],"concept":[{"heading":"① 多層就是連鎖律重複用","body":["y = e^{sin(x²)} 有三層：最外 e^u，中間 u = sin v，最裡 v = x²。","x 動一點點，v 動 2x 倍；v 動一點點，u 動 cos v 倍；u 動一點點，y 動 e^u 倍。全部相乘：","dy/dx = e^{sin(x²)} · cos(x²) · 2x。"],"tex":["\\frac{dy}{dx}=\\frac{dy}{du}\\cdot\\frac{du}{dv}\\cdot\\frac{dv}{dx}"]},{"heading":"② 剝洋蔥：由外往內，一層一個因子","body":["從最外層開始。每剝一層，就寫下這一層的導數，它裡面的整包原封不動。然後往裡一層，重複，直到剩下單純的 x。","有幾層就有幾個因子相乘。最常漏掉的是最裡面那一層，尤其是 2x、3 這種小東西。"]},{"heading":"③ 數層數：看計算順序","body":["sin³(2x) 是 (sin(2x))³。計算順序：先乘 2、再取 sin、最後三次方，所以三層：u³、sin v、2x。","√(1 + √x)：先開 √x、再加 1、最後開根號。外層 √u 給 1/(2√(1 + √x))；裡層 1 + √x 的導數是 (√x)′ = 1/(2√x)，加的 1 微分是 0。相乘得 1/(4√x √(1 + √x))。"]},{"heading":"④ 跟乘法、除法法則混在一起","body":["x² sin(3x)：最後一步是「乘」，所以先用乘法法則，(x²)′ sin(3x) + x² (sin(3x))′；第二項裡面才用連鎖律。","判斷的方法跟〈連鎖律 I：兩層〉一樣：最後一步做什麼運算，第一步就用那條法則。裡面遇到合成，再一層一層剝。"]},{"heading":"⑤ 為什麼可以一直乘下去","body":["三層 f(g(h(x)))：把 g(h(x)) 整個當成裡層，兩層的連鎖律給 f′(g(h(x))) · [g(h(x))]′。","[g(h(x))]′ 本身又是兩層，等於 g′(h(x)) · h′(x)。代回去就是三個因子相乘。更多層照樣一層一層代。"],"collapsible":true}],"workedExamples":[{"title":"三層：指數、正弦、平方","prompt":"d/dx e^{sin(x²)}","problemId":"dd-nest-002","steps":["最外 e^u：導數 e^u = e^{sin(x²)}，裡面不動。","中間 sin v：導數 cos v = cos(x²)。","最裡 x²：導數 2x。","三個相乘：2x cos(x²) e^{sin(x²)}。"],"answer":"2x cos(x²) e^{sin(x²)}"},{"title":"三層：次方、正弦、一次式","prompt":"y = sin³(2x)，求 y′","problemId":"lec-02-q2c","steps":["sin³(2x) = (sin(2x))³。最外 u³：導數 3u² = 3 sin²(2x)。","中間 sin v：導數 cos v = cos(2x)。","最裡 2x：導數 2。","相乘：3 sin²(2x) · cos(2x) · 2 = 6 sin²(2x) cos(2x)。"],"answer":"6 sin²(2x) cos(2x)"},{"title":"外面是乘法，裡面是合成","prompt":"d/dx x² sin(3x)","problemId":"der-026","steps":["最後一步是乘法，先用乘法法則：(x²)′ · sin(3x) + x² · (sin(3x))′。","(x²)′ = 2x。","(sin(3x))′ 用連鎖律：cos(3x) · 3。","合起來：2x sin(3x) + 3x² cos(3x)。"],"answer":"2x sin(3x) + 3x² cos(3x)"}],"pitfalls":["少乘一層，最常漏的是最裡面的 2x、3。","微分外層時，把裡層也改掉了。","混合題沒先看最外面是乘法，直接從某個 sin 開始用連鎖律。","把 sin³(2x) 數成兩層，漏了 2x。"],"checks":[{"ask":"d/dx cos(e^{2x}) 是？","options":[{"label":"−sin(e^{2x}) · e^{2x}","why":"漏了最裡層：e^{2x} 的導數是 2e^{2x}，那個 2 來自 2x。"},{"label":"−2e^{2x} sin(e^{2x})","correct":true},{"label":"−sin(2e^{2x})","why":"微分外層時把裡面也微分了。外層換成 −sin，裡面要原封不動是 e^{2x}，導數乘在外面。"}]},{"ask":"d/dx ln(sin(x³)) 是？","options":[{"label":"1/sin(x³)","why":"只微了最外層 ln。還要乘 sin(x³) 的導數 cos(x³) · 3x²。"},{"label":"cos(x³)/sin(x³)","why":"漏了最裡層 x³ 的導數 3x²。"},{"label":"3x² cos(x³)/sin(x³)","correct":true}]},{"ask":"x³ e^{−x²} 微分，第一步用什麼？","options":[{"label":"乘法法則","correct":true},{"label":"連鎖律","why":"e^{−x²} 那一個因式才需要連鎖律；整個式子最後一步是 x³ 乘 e^{−x²}。"},{"label":"冪次法則","why":"x³ 只是其中一個因式，整個式子不是 x 的次方。"}]},{"ask":"f(x) = ln(ln x)，f′(e) 是？","options":[{"label":"1","why":"只微了外層：1/ln x 代 e 得 1。還要乘裡層 ln x 的導數 1/x。"},{"label":"1/e","correct":true},{"label":"0","why":"那是函數值 f(e) = ln 1 = 0，不是導數。"}]}],"practice":[{"id":"dd-nest-002","core":true},{"id":"db-chain-003","core":true},{"id":"lec-02-q2c","core":true},{"id":"ch-mix-010","core":true},{"id":"der-026","core":true},{"id":"db-chain-002","core":true},{"id":"lec-02-q2d"},{"id":"dd-nest-001"},{"id":"dd-nest-004"},{"id":"ch-mix-002"},{"id":"ch-nest-002","challenge":true,"note":"挑戰：四層，e、sin、ln、x² + 1。"},{"id":"dd-nest-003","challenge":true,"note":"挑戰：三個根號疊在一起。"}]},"implicit-differentiation":{"id":"implicit-differentiation","prerequisites":["chain-rule","product-rule"],"next":["logarithmic-differentiation"],"related":["related-rates"],"objectives":["不把 y 解出來，直接對方程式兩邊微分，求 dy/dx。","微分含 y 的項時記得乘 y′（連鎖律），xy 這種項用乘法法則。","在曲線上的點代值求切線斜率，並知道分母為 0 時代表什麼。"],"concept":[{"heading":"① 曲線不一定寫得成 y = f(x)","body":["x² + y² = 25 是一個圓。解 y 會得到兩支：y = √(25 − x²) 與 y = −√(25 − x²)。x³ + y³ = 6xy 更麻煩，幾乎不可能好好解出 y。","可是曲線上每一點（大部分的點）還是有切線。我們想直接從方程式求斜率。"]},{"heading":"② 想法：把 y 當成 x 的函數","body":["在曲線的一小段上，y 是 x 的函數 y(x)，只是我們沒寫出它的式子。方程式兩邊都是 x 的函數而且相等，所以兩邊對 x 的導數也相等。","唯一的新東西：微分含 y 的項要用連鎖律。y² 是「平方」套在 y(x) 外面，導數是 2y · y′。同理 (y³)′ = 3y² y′、(sin y)′ = cos y · y′。","x 和 y 相乘的項用乘法法則：(xy)′ = 1 · y + x · y′。"],"tex":["\\frac{d}{dx}\\,y^2=2y\\,\\frac{dy}{dx}"]},{"heading":"③ 四個步驟","body":["兩邊對 x 微分 → 含 y′ 的項移到一邊，其他移到另一邊 → 提出 y′ → 除過去。","結果通常同時含 x 和 y。要某一點的斜率，就把那一點的 x、y 都代進去（先確認那一點真的在曲線上）。","〈相關變率〉會用同一招，只是改成對時間 t 微分。"]},{"heading":"④ 分母是 0 的時候","body":["圓的斜率是 y′ = −x/y。在 (5, 0)，分母 y = 0：那裡的切線是鉛直線，斜率不存在。這不是方法失靈——上半圓 y = √(25 − x²) 在 x = 5 也不可微。曲線本身在那裡就是直上直下。"]},{"heading":"⑤ 什麼時候「y 是 x 的函數」站得住","body":["上面默認了在那一點附近，曲線是某個可微函數 y(x) 的圖形。這不是永遠對：在圓的 (5, 0) 附近，同一個 x 對到上下兩個 y，曲線不是任何函數的圖形。","把方程式寫成 F(x, y) = c。多變數微積分會證明（隱函數定理）：如果 F 的偏導數連續，而且在那一點 F 對 y 的偏導數不是 0，那麼在那一點附近曲線就是某個可微函數 y(x) 的圖形。以圓來說，F 對 y 的偏導數是 2y，只在 y = 0 的兩點出事，正好是切線鉛直的地方。"],"collapsible":true}],"workedExamples":[{"title":"圓上一點的切線斜率","prompt":"x² + y² = 25，求 dy/dx 在 (3, 4)","problemId":"cx-app-001","steps":["先確認：3² + 4² = 25，點在圓上。","兩邊對 x 微分：2x + 2y y′ = 0（25 是常數，導數 0）。","解 y′：y′ = −x/y。","代 (3, 4)：y′ = −3/4。","對答案：這一點在上半圓 y = √(25 − x²)，直接微分 y′ = −x/√(25 − x²)，代 x = 3 得 −3/4，一樣。"],"answer":"−3/4"},{"title":"有 xy 項：用乘法法則","prompt":"xy + y² = 6，求 dy/dx 在 (1, 2)","problemId":"tb-imp-002","steps":["確認：1 · 2 + 2² = 6，點在曲線上。","微分：(xy)′ = y + x y′，(y²)′ = 2y y′，(6)′ = 0。得 y + x y′ + 2y y′ = 0。","含 y′ 的放一邊：y′(x + 2y) = −y，所以 y′ = −y/(x + 2y)。","代 (1, 2)：y′ = −2/(1 + 4) = −2/5。"],"answer":"−2/5","note":"這條曲線其實解得出 y = (−x + √(x² + 24))/2（取經過 (1, 2) 的那一支），直接微分也得 −2/5。"},{"title":"解不出 y 的曲線","prompt":"x³ + y³ = 6xy，求 dy/dx 在 (3, 3)","problemId":"cx-app-002","steps":["確認：27 + 27 = 54 = 6 · 3 · 3，點在曲線上。","微分：3x² + 3y² y′ = 6y + 6x y′（右邊 6xy 用乘法法則）。","整理：y′(3y² − 6x) = 6y − 3x²，同除以 3：y′ = (2y − x²)/(y² − 2x)。","代 (3, 3)：y′ = (6 − 9)/(9 − 6) = −1。"],"answer":"−1","note":"驗算用的是這條曲線的參數式 x = 6t/(1 + t³)、y = 6t²/(1 + t³)，t = 1 正好是 (3, 3)，斜率 = (dy/dt)/(dx/dt)。"}],"pitfalls":["y² 微分寫成 2y，漏了 y′。","xy 微分寫成 y′，或只寫 x y′，漏了乘法法則的另一項。","右邊的常數微分後忘了變成 0。","移項時正負號弄錯，整個答案差一個負號。","代進一個不在曲線上的點。"],"checks":[{"ask":"把 y 看成 x 的函數，d/dx (y³) 是？","options":[{"label":"3y²","why":"y 是 x 的函數，外層是三次方、裡層是 y(x)，連鎖律要再乘 y′。"},{"label":"3y² y′","correct":true},{"label":"0","why":"把 y 當成常數了。y 會隨 x 變，所以它的導數不是 0。"}]},{"ask":"d/dx (xy) 是？","options":[{"label":"y′","why":"這是各自微分再相乘 1 · y′。xy 是乘積，要用乘法法則。"},{"label":"x y′","why":"只寫了一半，還有 (x)′ · y = y。"},{"label":"y + x y′","correct":true}]},{"ask":"x² + y² = 13 在 (2, 3) 的 dy/dx 是？","options":[{"label":"−2/3","correct":true},{"label":"−3/2","why":"把 −x/y 寫成了 −y/x。從 2x + 2y y′ = 0 解出來是 y′ = −x/y。"},{"label":"2/3","why":"移項時漏了負號：2y y′ = −2x。"}]},{"ask":"x² + y² = 25 在 (5, 0)，公式 y′ = −x/y 的分母是 0。這表示？","options":[{"label":"切線是鉛直線，斜率不存在","correct":true},{"label":"斜率是 0","why":"斜率 0 是水平切線，發生在 x = 0 的 (0, ±5)。這裡是分母為 0，不是分子。"},{"label":"隱函數微分在這裡算錯了，要改用 y = √(25 − x²)","why":"√(25 − x²) 在 x = 5 一樣不可微。圓在那一點本來就直上直下，不是方法的問題。"}]}],"practice":[{"id":"cx-app-001","core":true},{"id":"tb-imp-001","core":true},{"id":"db-imp-001","core":true},{"id":"tb-imp-002","core":true},{"id":"lec-03-q1a","core":true},{"id":"cx-app-002","core":true},{"id":"lec-03-q1b","core":true},{"id":"tb-imp-004"},{"id":"dd-imp-005"},{"id":"db-imp-003"},{"id":"dd-imp-007"},{"id":"db-imp-005","challenge":true,"note":"挑戰：對 y′ = −x/y 再微分一次（除法法則，y′ 再代回去）。"},{"id":"lec-03-q1d","challenge":true,"note":"挑戰：二階導數，先求 y′ 再對 y′ 隱函數微分。"}]},"logarithmic-differentiation":{"id":"logarithmic-differentiation","prerequisites":["derivative-log","derivative-exp","chain-rule","implicit-differentiation"],"next":["inverse-trig-derivative"],"related":[],"objectives":["說出為什麼 xˣ 不能用冪次法則、也不能用指數函數的公式。","用「取 ln、兩邊微分、乘回 y」微分底與指數都含 x 的函數。","用對數把很多因式的乘除變成加減，再微分。"],"concept":[{"heading":"① 兩條公式都不能套","body":["冪次法則 (xⁿ)′ = n xⁿ⁻¹ 要指數是常數；(aˣ)′ = aˣ ln a 要底是常數。xˣ 的底和指數都在變，兩條都不適用。","硬套會得到 x · x^{x−1} = xˣ，或 xˣ ln x。正確答案是 xˣ(ln x + 1)，剛好是這兩個錯誤答案相加：底在變的貢獻，加上指數在變的貢獻。這是直覺，不是證明；證明就是下面的計算。"]},{"heading":"② 方法：取 ln，把指數拉下來","body":["y = xˣ（x > 0）。兩邊取 ln：ln y = x ln x。指數變成乘法了。","兩邊對 x 微分。左邊是 ln 套在 y(x) 外面，連鎖律給 y′/y；右邊用乘法法則給 ln x + 1。","y′/y = ln x + 1，最後乘回 y：y′ = xˣ(ln x + 1)。"],"tex":["\\ln y=x\\ln x\\ \\Rightarrow\\ \\frac{y'}{y}=\\ln x+1\\ \\Rightarrow\\ y'=x^x(\\ln x+1)"]},{"heading":"③ 同一件事的另一種寫法","body":["xˣ = e^{x ln x}（因為 e^{ln x} = x）。直接用連鎖律：(e^{x ln x})′ = e^{x ln x} · (ln x + 1) = xˣ(ln x + 1)。兩種寫法本質相同，挑順手的用。"]},{"heading":"④ 第二種用途：很多因式相乘除","body":["y = x² √(x + 1)/(x − 1)³。直接用乘法、除法法則很長。取 ln 把乘除變加減：ln y = 2 ln x + ½ ln(x + 1) − 3 ln(x − 1)。每一項都好微。","ln 只對正數有定義。y 可能是負的時候，改取 ln|y|：(ln|u|)′ = u′/u 一樣成立，所以只要 y ≠ 0，最後的公式照樣對。"]}],"workedExamples":[{"title":"xˣ","prompt":"y = xˣ（x > 0），求 y′，以及 x = 1 時的值","problemId":"lec-03-q2a","steps":["取 ln：ln y = x ln x。","兩邊微分：y′/y = 1 · ln x + x · (1/x) = ln x + 1。","乘回 y：y′ = xˣ(ln x + 1)。","x = 1：1¹ · (0 + 1) = 1。"],"answer":"y′ = xˣ(ln x + 1)；x = 1 時為 1"},{"title":"指數是三角函數","prompt":"y = x^{sin x}（x > 0），求 y′","problemId":"lec-03-q2b","steps":["取 ln：ln y = sin x · ln x。","右邊用乘法法則：cos x · ln x + sin x · (1/x)。","y′/y = cos x ln x + (sin x)/x。","乘回 y：y′ = x^{sin x}(cos x ln x + (sin x)/x)。"],"answer":"x^{sin x}(cos x ln x + (sin x)/x)"},{"title":"很多因式相乘除","prompt":"y = x² √(x + 1)/(x − 1)³（x > 1），求 y′","problemId":"lec-03-q2c","steps":["x > 1 時每個因式都是正的，可以直接取 ln：ln y = 2 ln x + ½ ln(x + 1) − 3 ln(x − 1)。","逐項微分：y′/y = 2/x + 1/(2(x + 1)) − 3/(x − 1)。","乘回 y：y′ = [x² √(x + 1)/(x − 1)³] · (2/x + 1/(2(x + 1)) − 3/(x − 1))。"],"answer":"x² √(x + 1)/(x − 1)³ · (2/x + 1/(2(x + 1)) − 3/(x − 1))"}],"pitfalls":["(xˣ)′ 寫成 x · x^{x−1}（把指數當常數）。","(xˣ)′ 寫成 xˣ ln x（把底當常數）。","算到 y′/y 就停，忘了乘回 y。","左邊 ln y 微分寫成 1/y，漏了 y′。","把 ln(x + 1) 拆成 ln x + ln 1。ln 只把乘除變加減，不拆加法。"],"checks":[{"ask":"d/dx xˣ（x > 0）是？","options":[{"label":"x · x^{x−1}","why":"這是冪次法則，它要指數是常數。xˣ 的指數也在變。"},{"label":"xˣ ln x","why":"這是 (aˣ)′ = aˣ ln a，它要底是常數。xˣ 的底也在變。"},{"label":"xˣ(ln x + 1)","correct":true}]},{"ask":"y = x^{2x}（x > 0），y′ 是？","options":[{"label":"x^{2x}(2 ln x + 2)","correct":true},{"label":"2 ln x + 2","why":"這是 y′/y。算完 ln y = 2x ln x 的導數之後還要乘回 y。"},{"label":"2x · x^{2x−1}","why":"把指數 2x 當成常數用了冪次法則。"}]},{"ask":"下面哪一個最需要用對數微分？","options":[{"label":"x⁵","why":"指數是常數，冪次法則就夠：5x⁴。"},{"label":"(sin x)ˣ","correct":true},{"label":"5ˣ","why":"底是常數，直接 5ˣ ln 5。"}]},{"ask":"f(x) = xˣ，f′(2) 是？","options":[{"label":"4","why":"用了冪次法則 x · x^{x−1}，代 2 得 2 · 2 = 4。"},{"label":"4 ln 2","why":"用了 aˣ 的公式 xˣ ln x，代 2 得 4 ln 2。"},{"label":"4(ln 2 + 1)","correct":true}]}],"practice":[{"id":"lec-03-q2a","core":true},{"id":"cx-exam-004","core":true},{"id":"dd-log-001","core":true},{"id":"der-040","core":true},{"id":"lec-03-q2b","core":true},{"id":"lec-03-q2c","core":true},{"id":"uni-der-002"},{"id":"depth-der-001"},{"id":"db-logd-002"},{"id":"dd-log-008"},{"id":"db-logd-004","challenge":true,"note":"挑戰：(1 + 1/x)ˣ，取 ln 後的 x ln(1 + 1/x) 要小心微分。"},{"id":"dd-imp-004","challenge":true,"note":"挑戰：x^y = y^x，取 ln 之後再隱函數微分。"}]},"inverse-trig-derivative":{"id":"inverse-trig-derivative","prerequisites":["inverse-function","inverse-trig","implicit-differentiation","chain-rule","derivative-trig"],"next":["higher-derivatives"],"related":[],"objectives":["用 (f⁻¹)′(b) = 1/f′(a)（其中 f(a) = b）求反函數在一點的導數，不必解出反函數。","推導並記住 arcsin、arccos、arctan 的導數，說得出 √ 為什麼取正。","反三角函數套連鎖律，例如 arcsin(x/4)、arctan(x²)。"],"concept":[{"heading":"① 圖像：鏡射把斜率變成倒數","body":["f 和 f⁻¹ 的圖形對 y = x 對稱：f 上的點 (a, b) 對應 f⁻¹ 上的點 (b, a)。鏡射把「x 方向」和「y 方向」對調，所以上升除以前進變成前進除以上升：斜率 m 變成 1/m。","所以：f⁻¹ 在 b 的導數，是 f 在 a 的導數的倒數，其中 f(a) = b。要 f′(a) ≠ 0，否則倒數不存在（那一點反函數的切線是鉛直的）。"],"tex":["(f^{-1})'(b)=\\frac{1}{f'(a)},\\qquad f(a)=b"]},{"heading":"② 公式從哪裡來（假設 f⁻¹ 可微）","body":["f(f⁻¹(x)) = x。兩邊對 x 微分，左邊用連鎖律：f′(f⁻¹(x)) · (f⁻¹)′(x) = 1。除過去就是上面的公式。","這個推法先假設了 f⁻¹ 可微。定理保證：f 在一個區間上連續且嚴格單調、在區間內部的 a 可微且 f′(a) ≠ 0，f⁻¹ 就在 b = f(a) 可微。"]},{"heading":"③ arcsin 與 arctan","body":["y = arcsin x 的意思是 sin y = x，而且 y 在 [−π/2, π/2]。對 x 隱函數微分：cos y · y′ = 1，y′ = 1/cos y。","要把 cos y 寫回 x：cos y = ±√(1 − sin² y) = ±√(1 − x²)。y 在 [−π/2, π/2]，那裡 cos y ≥ 0，所以取正號。x = ±1 時分母是 0，導數只在 −1 < x < 1 存在。","y = arctan x：tan y = x，y 在 (−π/2, π/2)。sec² y · y′ = 1，y′ = 1/sec² y = 1/(1 + tan² y) = 1/(1 + x²)，對所有 x 成立。","arccos x = π/2 − arcsin x，所以導數多一個負號。"],"tex":["(\\arcsin x)'=\\frac{1}{\\sqrt{1-x^2}},\\quad(\\arccos x)'=-\\frac{1}{\\sqrt{1-x^2}},\\quad(\\arctan x)'=\\frac{1}{1+x^2}"]},{"heading":"④ 定理的證明","body":["設 f 在區間 I 上連續、嚴格單調，在 a 可微且 f′(a) ≠ 0，b = f(a)。連續且嚴格單調的函數，反函數也連續（這一步本身需要中間值定理，這裡接受它）。","取 k ≠ 0 很小，令 x = f⁻¹(b + k)。因為 f⁻¹ 一對一，x ≠ a；因為 f⁻¹ 連續，k → 0 時 x → a。","[f⁻¹(b + k) − f⁻¹(b)]/k = (x − a)/(f(x) − f(a)) = 1 / [(f(x) − f(a))/(x − a)]。","k → 0 時 x → a 而且 x ≠ a，分母 → f′(a) ≠ 0，所以整個 → 1/f′(a)。"],"collapsible":true}],"workedExamples":[{"title":"不解反函數，求它的導數","prompt":"f(x) = x³ + x，求 (f⁻¹)′(2)","problemId":"db-inv-001","steps":["f′(x) = 3x² + 1 > 0，f 嚴格遞增，有反函數。","先找 a 使 f(a) = 2：a³ + a = 2，試 a = 1：1 + 1 = 2。所以 f⁻¹(2) = 1。","f′(1) = 3 + 1 = 4。","(f⁻¹)′(2) = 1/f′(1) = 1/4。"],"answer":"1/4","note":"最常見的錯是算 1/f′(2) = 1/13：2 是反函數的輸入，要先換成 f 的輸入 a = 1。"},{"title":"arcsin 套連鎖律","prompt":"d/dx arcsin(x/4)","problemId":"lec-03-q3b","steps":["外層 arcsin u，導數 1/√(1 − u²)；裡層 u = x/4，導數 1/4。","相乘：(1/4) · 1/√(1 − x²/16)。","化簡根號：1 − x²/16 = (16 − x²)/16，所以 √(1 − x²/16) = √(16 − x²)/4。","(1/4) · 4/√(16 − x²) = 1/√(16 − x²)（−4 < x < 4）。"],"answer":"1/√(16 − x²)"},{"title":"arctan 套連鎖律","prompt":"d/dx arctan(x²)","problemId":"db-itrig-002","steps":["外層 arctan u，導數 1/(1 + u²)；裡層 u = x²，導數 2x。","1/(1 + (x²)²) · 2x = 2x/(1 + x⁴)。"],"answer":"2x/(1 + x⁴)"}],"pitfalls":["(f⁻¹)′(b) 算成 1/f′(b)，忘了先找 a = f⁻¹(b)。","把 arcsin x 當成 1/sin x。sin⁻¹ x 這個寫法指的是反函數，不是倒數。","忘了連鎖律：arctan(x²) 寫成 1/(1 + x⁴)。","把 (x²)² 寫成 x²，得到 2x/(1 + x²)。","arccos 的導數漏了負號。"],"checks":[{"ask":"f(x) = x³ + x，(f⁻¹)′(2) 是？","options":[{"label":"1/13","why":"這是 1/f′(2)。2 是反函數的輸入，要先找 f(a) = 2 的 a = 1，再算 1/f′(1)。"},{"label":"1/4","correct":true},{"label":"4","why":"這是 f′(1)，忘了取倒數。"}]},{"ask":"arctan x 在 x = 1 的導數是？","options":[{"label":"π/4","why":"這是函數值 arctan 1，不是導數。"},{"label":"2","why":"倒數弄反了：導數是 1/(1 + x²) = 1/2，不是 1 + x²。"},{"label":"1/2","correct":true}]},{"ask":"d/dx arcsin(2x) 是？","options":[{"label":"2/√(1 − 4x²)","correct":true},{"label":"1/√(1 − 4x²)","why":"外層對了，忘了乘裡層 2x 的導數 2。"},{"label":"2/√(1 − 2x²)","why":"(2x)² 是 4x²，不是 2x²。"}]},{"ask":"推導 (arcsin x)′ 時，cos y = √(1 − x²) 為什麼取正號？","options":[{"label":"因為 y = arcsin x 在 [−π/2, π/2]，那裡 cos y ≥ 0","correct":true},{"label":"因為根號一律取正","why":"√ 本身是正的沒錯，但問題是 cos y 該等於 +√ 還是 −√；決定這件事的是 y 的範圍。"},{"label":"因為 x > 0","why":"x 可以是負的，例如 arcsin(−1/2) = −π/6，那裡 cos 仍然是正的。"}]}],"practice":[{"id":"db-inv-001","core":true},{"id":"lec-03-q3d","core":true},{"id":"dd-invf-003","core":true},{"id":"world-004","core":true},{"id":"cx-der-008","core":true},{"id":"db-itrig-001","core":true},{"id":"db-itrig-002","core":true},{"id":"lec-03-q3b"},{"id":"der-028"},{"id":"exam-der-017"},{"id":"hd-009"},{"id":"db-inv-003"},{"id":"dd-inv-003","challenge":true,"note":"挑戰：x arcsin x + √(1 − x²) 微分後會大量消掉，只剩 arcsin x。"},{"id":"depth-der-015","challenge":true,"note":"挑戰：arccos 套連鎖律，化簡時要用到 x > 0。"}]},"higher-derivatives":{"id":"higher-derivatives","prerequisites":["derivative-power-rules","derivative-trig","derivative-exp","product-rule","chain-rule"],"next":["critical-points"],"related":["second-derivative","concavity","taylor-polynomial"],"objectives":["求二階、三階導函數，看懂 f″、f‴、f⁽ⁿ⁾、d²y/dx² 這些記號。","用位置、速度、加速度解釋 s′ 與 s″。","找出 sin、cos、e^{kx}、xⁿ 的 n 階導數規律，在 x = 0 代值。"],"concept":[{"heading":"① 導函數也是函數，可以再微分","body":["f′ 本身是一個函數，對它再微分一次，得到二階導函數 f″；再一次是 f‴；第 n 次寫成 f⁽ⁿ⁾（括號是為了跟 n 次方分開）。用萊布尼茲記號寫成 d²y/dx²、dⁿy/dxⁿ。","例：f(x) = x⁴，f′ = 4x³，f″ = 12x²，f‴ = 24x，f⁽⁴⁾ = 24，f⁽⁵⁾ = 0。"]},{"heading":"② 意義：變化率的變化率","body":["直線上運動的位置 s(t)。s′(t) 是速度：位置變多快。s″(t) 是加速度：速度變多快。","在圖形上，f′ 是切線斜率，f″ 就是「斜率變多快」。f″ > 0 表示斜率越來越大，曲線往上彎；這是〈二階導數〉與〈凹向上／凹向下〉的主題。"]},{"heading":"③ 每一次都是一次完整的微分","body":["第二次微分時，乘法法則、連鎖律照樣要用。(x eˣ)′ = (x + 1)eˣ 還是乘積，再微分一次要再用一次乘法法則。","f″ 不是 (f′)²。f″ 是「微分兩次」，(f′)² 是「微分一次再平方」。"]},{"heading":"④ 會循環或有規律的家族","body":["sin x → cos x → −sin x → −cos x → sin x：每 4 階回到原樣。第 n 階看 n 除以 4 的餘數。","e^{kx} 每微分一次多乘一個 k：第 n 階是 kⁿ e^{kx}。sin(kx)、cos(kx) 也是每次多乘一個 k，同時照上面的順序循環。","xⁿ 微分 n 次得常數 n!，再多微一次就是 0。","這些在 x = 0 的值，之後會用來寫〈Taylor 多項式〉。"]}],"workedExamples":[{"title":"位置、速度、加速度","prompt":"s(t) = t³ − 6t² + 9t（公尺，t 秒），求加速度 a(t)","problemId":"lec-02-q4a","steps":["速度 v(t) = s′(t) = 3t² − 12t + 9。","加速度 a(t) = v′(t) = s″(t) = 6t − 12。","例如 t = 1 時 v = 0（瞬間停住），a = −6，表示速度正在往負的方向變。"],"answer":"a(t) = 6t − 12"},{"title":"第二次也要用乘法法則","prompt":"d²/dx² (x eˣ)","problemId":"der-029","steps":["第一次：(x eˣ)′ = 1 · eˣ + x · eˣ = (x + 1)eˣ。","第二次，(x + 1)eˣ 仍是乘積：1 · eˣ + (x + 1) · eˣ = (x + 2)eˣ。"],"answer":"(x + 2)eˣ","note":"規律：再微下去是 (x + 3)eˣ、(x + 4)eˣ……第 n 階是 (x + n)eˣ。"},{"title":"找循環","prompt":"d⁴/dx⁴ cos(3x) 在 x = 0 的值","problemId":"depth-der-017","steps":["每微分一次，連鎖律多乘一個 3；cos → −sin → −cos → sin → cos 循環。","第 1 階 −3 sin(3x)，第 2 階 −9 cos(3x)，第 3 階 27 sin(3x)，第 4 階 81 cos(3x)。","代 x = 0：81 cos 0 = 81。"],"answer":"81"},{"title":"從前幾階猜出第 n 階","prompt":"f(x) = 1/(1 − x)，求 f⁽⁷⁾(0)","problemId":"hd-001","steps":["寫成 f(x) = (1 − x)⁻¹。連鎖律：裡層 1 − x 的導數是 −1，跟冪次法則拉下來的負號相乘變成正的。","f′ = (1 − x)⁻²，f″ = 2(1 − x)⁻³，f‴ = 2 · 3 (1 − x)⁻⁴ = 6(1 − x)⁻⁴。","規律：每微分一次，把目前的次方數乘到前面、次方數加 1。所以 f⁽ⁿ⁾(x) = n!/(1 − x)ⁿ⁺¹。","n = 7、x = 0：7! = 5040。"],"answer":"5040","note":"「看前幾階猜規律」要用數學歸納法才算證明：假設 f⁽ⁿ⁾ = n!(1 − x)^{−(n+1)}，再微分一次得 n!(n + 1)(1 − x)^{−(n+2)} = (n + 1)!(1 − x)^{−(n+2)}，規律延續。"}],"pitfalls":["把 f″ 當成 (f′)²。","第二次微分時忘了乘法法則或連鎖律。","sin 的高階導數循環數錯：週期是 4，不是 2。","e^{kx} 微分 n 次忘了每次乘 k，或把 kⁿ 寫成 nk。","先代 x = a 再微分，得到常數的導數 0。"],"checks":[{"ask":"f(x) = x⁴，f‴(x) 是？","options":[{"label":"12x²","why":"這是 f″，只微分了兩次。"},{"label":"24x","correct":true},{"label":"64x⁹","why":"這是 (f′)³ = (4x³)³。f‴ 是微分三次，不是一階導數的三次方。"}]},{"ask":"s(t) = t³ − 3t²，t = 2 時的加速度是？","options":[{"label":"0","why":"這是速度 s′(2) = 3 · 4 − 6 · 2 = 0。加速度要再微分一次。"},{"label":"6","correct":true},{"label":"−4","why":"這是位置 s(2) = 8 − 12 = −4，還沒微分。"}]},{"ask":"d¹⁰/dx¹⁰ sin x 是？","options":[{"label":"sin x","why":"以為偶數階都回到 sin x。其實每 4 階才回到原樣；10 除以 4 餘 2。"},{"label":"cos x","why":"循環數錯了。10 除以 4 餘 2，對應第 2 階 −sin x。"},{"label":"−sin x","correct":true}]},{"ask":"d⁵/dx⁵ e^{2x} 在 x = 0 的值是？","options":[{"label":"32","correct":true},{"label":"10","why":"每微分一次乘 2，五次是 2⁵ = 32，不是 2 × 5。"},{"label":"1","why":"忘了連鎖律：e^{2x} 每微分一次都要乘裡層 2x 的導數 2。"}]}],"practice":[{"id":"lec-02-q4a","core":true},{"id":"dd-kin-004","core":true},{"id":"db-mot-002","core":true},{"id":"dd-kin-003","core":true},{"id":"der-029","core":true},{"id":"depth-der-017","core":true},{"id":"uni-der-019","core":true},{"id":"hc-der-009"},{"id":"depth-der-004"},{"id":"exam-der-007"},{"id":"burst-der-001"},{"id":"uni-der-003","challenge":true,"note":"挑戰：e^{2x} sin x 微分三次，每次都要乘法法則。"}]}});
